                  <Label
                    htmlFor={`day-${row.dayOfWeek}-interval`}
                    className="text-xs uppercase tracking-[0.18em] text-muted-foreground"
                  >
                    Interval (min)
                  </Label>
                  <Input
                    id={`day-${row.dayOfWeek}-interval`}
                    name={`day-${row.dayOfWeek}-interval`}
                    type="number"
                    min={1}
                    max={180}
                    value={row.reservationIntervalMinutes}
