export function EmailTemplatesSection({ restaurantId, restaurantName }: EmailTemplatesSectionProps) {
  const templatesQuery = useOpsRestaurantEmailTemplates(restaurantId);
  const updateMutation = useOpsUpdateRestaurantEmailTemplate(restaurantId);
  const resetMutation = useOpsResetRestaurantEmailTemplate(restaurantId);
  const previewMutation = useOpsPreviewRestaurantEmailTemplate(restaurantId);
  const testSendMutation = useOpsSendRestaurantEmailTemplateTest(restaurantId);

  const [selectedTemplateKey, setSelectedTemplateKey] = useState<RestaurantBookingEmailTemplateKey | null>(null);
  const [selectedVariantId, setSelectedVariantId] = useState<string | null>(null);
  const [drafts, setDrafts] = useState<Partial<Record<RestaurantBookingEmailTemplateKey, RestaurantEmailTemplateVariant[]>>>({});
  const [searchQuery, setSearchQuery] = useState('');
  const [previewDevice, setPreviewDevice] = useState<'desktop' | 'mobile'>('desktop');
  const [testEmail, setTestEmail] = useState('');

  const deferredSearch = useDeferredValue(searchQuery.trim().toLowerCase());
  const templateMap = useMemo(() => buildTemplateMap(templatesQuery.data), [templatesQuery.data]);
  const allTemplates = useMemo(
    () => templatesQuery.data?.groups.flatMap((group) => group.templates) ?? [],
    [templatesQuery.data],
  );

  useEffect(() => {
    if (selectedTemplateKey && templateMap.has(selectedTemplateKey)) {
      return;
    }
    const firstTemplate = allTemplates[0];
    if (firstTemplate) {
      setSelectedTemplateKey(firstTemplate.key);
    }
  }, [allTemplates, selectedTemplateKey, templateMap]);

  const filteredGroups = useMemo(() => {
    if (!templatesQuery.data) return [];
    if (!deferredSearch) return templatesQuery.data.groups;

    return templatesQuery.data.groups
      .map((group) => ({
        ...group,
        templates: group.templates.filter((template) => {
          const haystack = `${group.title} ${template.title} ${template.description}`.toLowerCase();
          return haystack.includes(deferredSearch);
        }),
      }))
      .filter((group) => group.templates.length > 0);
  }, [deferredSearch, templatesQuery.data]);

  const baseTemplate = selectedTemplateKey ? templateMap.get(selectedTemplateKey) ?? null : null;
  const currentVariants = useMemo(() => {
    if (!selectedTemplateKey || !baseTemplate) return [];
    return drafts[selectedTemplateKey] ?? baseTemplate.variants;
  }, [baseTemplate, drafts, selectedTemplateKey]);

  const isCurrentDirty = useMemo(() => {
    if (!selectedTemplateKey || !baseTemplate) return false;
    return normalizeVariantsForCompare(currentVariants) !== normalizeVariantsForCompare(baseTemplate.variants);
  }, [baseTemplate, currentVariants, selectedTemplateKey]);

  const hasDirtyDrafts = useMemo(
    () =>
      Object.entries(drafts).some(([key, variants]) => {
        if (!variants) return false;
        const template = templateMap.get(key as RestaurantBookingEmailTemplateKey);
        if (!template) return false;
        return normalizeVariantsForCompare(variants) !== normalizeVariantsForCompare(template.variants);
      }),
    [drafts, templateMap],
  );

  useEffect(() => {
    const handler = (event: BeforeUnloadEvent) => {
      if (!hasDirtyDrafts) {
        return;
      }
      event.preventDefault();
      event.returnValue = '';
    };

    window.addEventListener('beforeunload', handler);
    return () => window.removeEventListener('beforeunload', handler);
  }, [hasDirtyDrafts]);

  useEffect(() => {
    if (!currentVariants.length) {
      setSelectedVariantId(null);
      return;
    }

    if (selectedVariantId && currentVariants.some((variant) => variant.id === selectedVariantId)) {
      return;
    }

    setSelectedVariantId(currentVariants[0]!.id);
  }, [currentVariants, selectedVariantId]);

  useEffect(() => {
    if (!restaurantId || !selectedTemplateKey || !currentVariants.length) {
      return;
    }

    const timeoutId = window.setTimeout(() => {
      previewMutation.mutate({
        templateKey: selectedTemplateKey,
        payload: {
          preferredVariantId: selectedVariantId ?? undefined,
          variants: currentVariants,
        },
      });
    }, 180);

    return () => window.clearTimeout(timeoutId);
  }, [currentVariants, previewMutation, restaurantId, selectedTemplateKey, selectedVariantId]);

  const currentVariant = currentVariants.find((variant) => variant.id === selectedVariantId) ?? null;
  const showCueField = templateSupportsCueField(selectedTemplateKey);
  const showAskField = templateSupportsAskField(selectedTemplateKey);

  const updateCurrentVariants = (
    updater: (variants: RestaurantEmailTemplateVariant[]) => RestaurantEmailTemplateVariant[],
  ) => {
    if (!selectedTemplateKey) return;
    setDrafts((current) => {
      const template = templateMap.get(selectedTemplateKey);
      const baseline = current[selectedTemplateKey] ?? template?.variants ?? [];
      return {
        ...current,
        [selectedTemplateKey]: updater(baseline),
      };
    });
  };

  const updateCurrentVariant = (
    variantId: string,
    updater: (variant: RestaurantEmailTemplateVariant) => RestaurantEmailTemplateVariant,
  ) => {
    updateCurrentVariants((variants) =>
      variants.map((variant) => (variant.id === variantId ? updater(variant) : variant)),
    );
  };

  const handleAddVariant = () => {
    if (!selectedTemplateKey || !baseTemplate || currentVariants.length >= MAX_RESTAURANT_EMAIL_TEMPLATE_VARIANTS) {
      return;
    }

    const seed = currentVariant ?? currentVariants[currentVariants.length - 1] ?? baseTemplate.defaultVariants[0];
    const nextVariant: RestaurantEmailTemplateVariant = {
      ...seed,
      id: createVariantId(selectedTemplateKey),
      name: `Variant ${currentVariants.length + 1}`,
      order: currentVariants.length,
      isActive: true,
    };

    updateCurrentVariants((variants) => [...variants, nextVariant]);
    setSelectedVariantId(nextVariant.id);
  };

  const handleMoveVariant = (variantId: string, direction: -1 | 1) => {
    updateCurrentVariants((variants) => {
      const ordered = [...variants].sort((left, right) => left.order - right.order);
      const index = ordered.findIndex((variant) => variant.id === variantId);
      const targetIndex = index + direction;
      if (index < 0 || targetIndex < 0 || targetIndex >= ordered.length) {
        return variants;
      }

      const swapped = [...ordered];
      [swapped[index], swapped[targetIndex]] = [swapped[targetIndex]!, swapped[index]!];
      return swapped.map((variant, nextIndex) => ({ ...variant, order: nextIndex }));
    });
  };

  const handleDeleteVariant = (variantId: string) => {
    if (currentVariants.length <= 1) {
      toast.error('Each template needs at least one variant.');
      return;
    }

    updateCurrentVariants((variants) =>
      variants
        .filter((variant) => variant.id !== variantId)
        .map((variant, index) => ({ ...variant, order: index })),
    );

    if (selectedVariantId === variantId) {
      const nextVariant = currentVariants.find((variant) => variant.id !== variantId);
      setSelectedVariantId(nextVariant?.id ?? null);
    }
  };

  const handleDiscardDraft = () => {
    if (!selectedTemplateKey) return;
    setDrafts((current) => {
      const next = { ...current };
      delete next[selectedTemplateKey];
      return next;
    });
  };

  const handleSave = async () => {
    if (!selectedTemplateKey) return;

    try {
      await updateMutation.mutateAsync({
        templateKey: selectedTemplateKey,
        variants: currentVariants,
      });
      setDrafts((current) => {
        const next = { ...current };
        delete next[selectedTemplateKey];
        return next;
      });
      toast.success('Template saved', {
        description: 'Restaurant-specific copy variants are now live for future sends.',
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unable to save template';
      toast.error('Save failed', { description: message });
    }
  };

  const handleResetTemplate = async (templateKey: RestaurantBookingEmailTemplateKey) => {
    const template = templateMap.get(templateKey);
    if (!template || template.status === 'default') {
      return;
    }

    const confirmed = window.confirm(`Reset "${template.title}" back to the system default variants?`);
    if (!confirmed) return;

    try {
      await resetMutation.mutateAsync({ templateKey });
      setDrafts((current) => {
        const next = { ...current };
        delete next[templateKey];
        return next;
      });
      toast.success('Template reset', {
        description: `${template.title} is using the default copy again.`,
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unable to reset template';
      toast.error('Reset failed', { description: message });
    }
  };

  const handleSendTest = async () => {
    if (!selectedTemplateKey) return;
    if (!testEmail.trim()) {
      toast.error('Enter a test email address first.');
      return;
    }

    try {
      const result = await testSendMutation.mutateAsync({
        templateKey: selectedTemplateKey,
        payload: {
          toEmail: testEmail.trim(),
          preferredVariantId: selectedVariantId ?? undefined,
          variants: currentVariants,
        },
      });
      toast.success('Test email sent', {
        description: `Delivered to ${testEmail.trim()} via ${result.provider}.`,
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unable to send test email';
      toast.error('Test send failed', { description: message });
    }
  };

  if (!restaurantId) {
    return (
      <SettingsCard
        title="Email Templates"
        description="Select a restaurant to manage its booking email variants."
      >
        <p className="text-sm text-muted-foreground">
          Choose a restaurant using the sidebar switcher to browse and customize booking email copy.
        </p>
      </SettingsCard>
    );
  }

  if (templatesQuery.isLoading && !templatesQuery.data) {
    return (
      <div className="grid gap-6 xl:grid-cols-[320px,minmax(0,1fr),380px]">
        <SettingsCard title="Template gallery" description="Loading template groups…">
          <div className="space-y-4">
            <Skeleton className="h-10 w-full" />
            <Skeleton className="h-28 w-full" />
            <Skeleton className="h-28 w-full" />
            <Skeleton className="h-28 w-full" />
          </div>
        </SettingsCard>
        <SettingsCard title="Editor" description="Loading selected template…">
          <div className="space-y-4">
            <Skeleton className="h-12 w-full" />
            <Skeleton className="h-24 w-full" />
            <Skeleton className="h-28 w-full" />
            <Skeleton className="h-12 w-full" />
          </div>
        </SettingsCard>
        <SettingsCard title="Preview" description="Loading live preview…">
          <Skeleton className="h-[720px] w-full" />
        </SettingsCard>
      </div>
    );
  }

  if (templatesQuery.error) {
    return (
      <SettingsCard title="Email Templates" description="Manage booking confirmation, reminder, and review copy.">
        <Alert variant="destructive">
          <AlertTitle>Unable to load email templates</AlertTitle>
          <AlertDescription>{templatesQuery.error.message}</AlertDescription>
        </Alert>
      </SettingsCard>
    );
  }

  return (
    <div className="space-y-4">
      {!templatesQuery.data?.canEdit ? (
        <Alert variant="info">
          <Sparkles className="size-4" />
          <AlertTitle>View only</AlertTitle>
          <AlertDescription>
            You can review {restaurantName}&apos;s template setup here, but only owners and managers can change copy or send tests.
          </AlertDescription>
        </Alert>
      ) : null}

      <div className="grid gap-6 xl:grid-cols-[320px,minmax(0,1fr),380px]">
        <SettingsCard
          title="Template Gallery"
          description="Browse guest-facing booking emails by journey stage."
          className="h-fit"
        >
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="template-search" className="sr-only">
                Search email templates
              </Label>
              <div className="relative">
                <Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                <Input
                  id="template-search"
                  name="template-search"
                  value={searchQuery}
                  onChange={(event) => setSearchQuery(event.target.value)}
                  placeholder="Search templates…"
                  className="pl-9"
                />
              </div>
            </div>

            <div className="space-y-5">
              {filteredGroups.map((group) => (
                <section key={group.key} className="space-y-2">
                  <div className="space-y-1">
                    <div className="text-sm font-semibold text-foreground">{group.title}</div>
                    <p className="text-xs text-muted-foreground">{group.description}</p>
                  </div>
                  <div className="space-y-3">
                    {group.templates.map((template) => {
                      const active = selectedTemplateKey === template.key;
                      const draftForTemplate = drafts[template.key];
                      const isDirty =
                        Boolean(draftForTemplate) &&
                        normalizeVariantsForCompare(draftForTemplate ?? []) !== normalizeVariantsForCompare(template.variants);

                      return (
                        <div
                          key={template.key}
                          onClick={() => setSelectedTemplateKey(template.key)}
                          onKeyDown={(event) => {
                            if (event.key === 'Enter' || event.key === ' ') {
                              event.preventDefault();
                              setSelectedTemplateKey(template.key);
                            }
                          }}
                          role="button"
                          tabIndex={0}
                          className={cn(
                            'w-full rounded-2xl border p-4 text-left transition hover:border-primary/40 hover:bg-muted/30',
                            active ? 'border-primary bg-primary/5 shadow-sm' : 'border-border/60',
                          )}
                        >
                          <div className="flex items-start justify-between gap-3">
                            <div className="space-y-1">
                              <div className="font-medium text-foreground">{template.title}</div>
                              <p className="text-xs leading-relaxed text-muted-foreground">{template.description}</p>
                            </div>
                            <Badge variant={getStatusBadgeVariant(template.status)}>{getStatusLabel(template.status)}</Badge>
                          </div>

                          <div className="mt-4 flex items-center justify-between gap-3">
                            <VariantCountMeter
                              activeCount={(draftForTemplate ?? template.variants).filter((variant) => variant.isActive).length}
                              totalCount={(draftForTemplate ?? template.variants).length}
                            />
                            {isDirty ? <Badge variant="outline">Unsaved</Badge> : null}
                          </div>

                          <div className="mt-4 flex flex-wrap gap-2">
                            <Button type="button" size="sm" variant={active ? 'default' : 'outline'}>
                              <PenSquare />
                              Edit
                            </Button>
                            <Button
                              type="button"
                              size="sm"
                              variant="outline"
                              onClick={(event) => {
                                event.stopPropagation();
                                setSelectedTemplateKey(template.key);
                              }}
                            >
                              <Eye />
                              Preview
                            </Button>
                            <Button
                              type="button"
                              size="sm"
                              variant="ghost"
                              onClick={(event) => {
                                event.stopPropagation();
                                void handleResetTemplate(template.key);
                              }}
                              disabled={!templatesQuery.data?.canEdit || template.status === 'default' || resetMutation.isPending}
                            >
                              <RefreshCcw />
                              Reset
                            </Button>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </section>
              ))}

              {filteredGroups.length === 0 ? (
                <div className="rounded-xl border border-dashed border-border px-4 py-8 text-center text-sm text-muted-foreground">
                  No templates match “{searchQuery}”.
                </div>
              ) : null}
            </div>
          </div>
        </SettingsCard>

        <SettingsCard
          title={baseTemplate?.title ?? 'Template Editor'}
          description={baseTemplate?.description ?? 'Choose a template to edit its copy variants.'}
          headerAction={
            baseTemplate ? (
              <div className="flex items-center gap-2">
                <Badge variant={getStatusBadgeVariant(baseTemplate.status)}>{getStatusLabel(baseTemplate.status)}</Badge>
                {isCurrentDirty ? <Badge variant="outline">Unsaved</Badge> : null}
              </div>
            ) : null
          }
          footer={
            baseTemplate ? (
              <div className="flex w-full flex-col gap-4">
                <div className="flex flex-wrap items-center gap-3">
                  <Label htmlFor="email-template-test-email" className="sr-only">
                    Test email address
                  </Label>
                  <Input
                    id="email-template-test-email"
                    name="email-template-test-email"
                    type="email"
                    value={testEmail}
                    onChange={(event) => setTestEmail(event.target.value)}
                    placeholder="Send a test email to…"
                    className="max-w-sm"
                    disabled={!templatesQuery.data?.canEdit}
                  />
                  <Button
                    type="button"
                    variant="outline"
                    onClick={() => void handleSendTest()}
                    disabled={!templatesQuery.data?.canEdit || testSendMutation.isPending}
                  >
                    <Send />
                    {testSendMutation.isPending ? 'Sending…' : 'Send Test'}
                  </Button>
                </div>
                <div className="flex flex-wrap items-center justify-between gap-3">
                  <p className="text-xs text-muted-foreground">
                    System layout, booking facts, delivery rules, and destination URLs stay locked. Only copy variants are editable here.
                  </p>
                  <div className="flex flex-wrap items-center gap-2">
                    <Button
                      type="button"
                      variant="ghost"
                      onClick={handleDiscardDraft}
                      disabled={!templatesQuery.data?.canEdit || !isCurrentDirty}
                    >
                      Discard changes
                    </Button>
                    <Button
                      type="button"
                      variant="outline"
                      onClick={() => void handleResetTemplate(baseTemplate.key)}
                      disabled={!templatesQuery.data?.canEdit || resetMutation.isPending || baseTemplate.status === 'default'}
                    >
                      <RefreshCcw />
                      Reset to default
                    </Button>
                    <Button
                      type="button"
                      onClick={() => void handleSave()}
                      disabled={!templatesQuery.data?.canEdit || updateMutation.isPending || !isCurrentDirty}
                    >
                      <Save />
                      {updateMutation.isPending ? 'Saving…' : 'Save template'}
                    </Button>
                  </div>
                </div>
              </div>
            ) : null
          }
        >
          {!baseTemplate || !currentVariant ? (
            <div className="rounded-xl border border-dashed border-border px-4 py-10 text-sm text-muted-foreground">
              Select a template from the left to manage its variants.
            </div>
          ) : (
            <div className="space-y-6">
              <div className="flex flex-wrap items-center justify-between gap-3 rounded-2xl border bg-muted/20 p-4">
                <div className="space-y-1">
                  <div className="text-sm font-medium text-foreground">Variant manager</div>
                  <p className="text-xs text-muted-foreground">
                    Keep up to {MAX_RESTAURANT_EMAIL_TEMPLATE_VARIANTS} variants active or inactive. Only active variants rotate in production.
                  </p>
                </div>
                <Button
                  type="button"
                  variant="outline"
                  onClick={handleAddVariant}
                  disabled={!templatesQuery.data?.canEdit || currentVariants.length >= MAX_RESTAURANT_EMAIL_TEMPLATE_VARIANTS}
                >
                  <Plus />
                  Add Variant
                </Button>
              </div>

              <div className="grid gap-4 lg:grid-cols-[220px,minmax(0,1fr)]">
                <div className="space-y-3">
                  {currentVariants
                    .slice()
                    .sort((left, right) => left.order - right.order)
                    .map((variant, index, orderedVariants) => {
                      const active = selectedVariantId === variant.id;
                      return (
                        <div
                          key={variant.id}
                          onClick={() => setSelectedVariantId(variant.id)}
                          onKeyDown={(event) => {
                            if (event.key === 'Enter' || event.key === ' ') {
                              event.preventDefault();
                              setSelectedVariantId(variant.id);
                            }
                          }}
                          role="button"
                          tabIndex={0}
                          className={cn(
                            'w-full rounded-2xl border p-3 text-left transition',
                            active ? 'border-primary bg-primary/5 shadow-sm' : 'border-border/60 hover:bg-muted/30',
                          )}
                        >
                          <div className="flex items-start justify-between gap-3">
                            <div className="space-y-1">
                              <div className="text-sm font-medium text-foreground">{variant.name}</div>
                              <div className="text-xs text-muted-foreground">{variant.headline}</div>
                            </div>
                            <Badge variant={variant.isActive ? 'secondary' : 'outline'}>
                              {variant.isActive ? 'Active' : 'Inactive'}
                            </Badge>
                          </div>
                          <div className="mt-3 flex items-center gap-1">
                            <Button
                              type="button"
                              size="icon-sm"
                              variant="ghost"
                              disabled={!templatesQuery.data?.canEdit || index === 0}
                              onClick={(event) => {
                                event.stopPropagation();
                                handleMoveVariant(variant.id, -1);
                              }}
                            >
                              <ChevronUp />
                            </Button>
                            <Button
                              type="button"
                              size="icon-sm"
                              variant="ghost"
                              disabled={!templatesQuery.data?.canEdit || index === orderedVariants.length - 1}
                              onClick={(event) => {
                                event.stopPropagation();
                                handleMoveVariant(variant.id, 1);
                              }}
                            >
                              <ChevronDown />
                            </Button>
                            <Button
                              type="button"
                              size="sm"
                              variant="ghost"
                              className="ml-auto"
                              disabled={!templatesQuery.data?.canEdit || currentVariants.length <= 1}
                              onClick={(event) => {
                                event.stopPropagation();
                                handleDeleteVariant(variant.id);
                              }}
                            >
                              Remove
                            </Button>
                          </div>
                        </div>
                      );
                    })}
                </div>

                <div className="space-y-5 rounded-2xl border border-border/60 bg-background p-5">
                  <div className="grid gap-2">
                    <Label htmlFor="variant-name">Internal variant name</Label>
                    <Input
                      id="variant-name"
                      value={currentVariant.name}
                      onChange={(event) =>
                        updateCurrentVariant(currentVariant.id, (variant) => ({
                          ...variant,
                          name: event.target.value,
                        }))
                      }
                      disabled={!templatesQuery.data?.canEdit}
                    />
                  </div>

                  <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl bg-muted/30 px-4 py-3">
                    <div className="space-y-1">
                      <Label
                        htmlFor={`variant-active-${currentVariant.id}`}
                        className="text-sm font-medium text-foreground"
                      >
                        Rotate this variant in production
                      </Label>
                      <div className="text-xs text-muted-foreground">
                        Inactive variants stay in the editor but are skipped by live sends.
                      </div>
                    </div>
                    <Switch
                      id={`variant-active-${currentVariant.id}`}
                      checked={currentVariant.isActive}
                      onCheckedChange={(checked) =>
                        updateCurrentVariant(currentVariant.id, (variant) => ({
                          ...variant,
                          isActive: checked,
                        }))
                      }
                      disabled={!templatesQuery.data?.canEdit}
                    />
                  </div>

                  <div className="grid gap-2">
                    <Label htmlFor="variant-headline">Headline</Label>
                    <Input
                      id="variant-headline"
                      value={currentVariant.headline}
                      onChange={(event) =>
                        updateCurrentVariant(currentVariant.id, (variant) => ({
                          ...variant,
                          headline: event.target.value,
                        }))
                      }
                      disabled={!templatesQuery.data?.canEdit}
                    />
                  </div>

                  <div className="grid gap-2">
                    <Label htmlFor="variant-intro">Intro copy</Label>
                    <Textarea
                      id="variant-intro"
                      value={currentVariant.intro}
                      onChange={(event) =>
                        updateCurrentVariant(currentVariant.id, (variant) => ({
                          ...variant,
                          intro: event.target.value,
                        }))
                      }
                      className="min-h-[160px]"
                      disabled={!templatesQuery.data?.canEdit}
                    />
                  </div>

                  {showCueField ? (
                    <div className="grid gap-2">
                      <Label htmlFor="variant-cue">Photo cue</Label>
                      <Textarea
                        id="variant-cue"
                        value={currentVariant.cue}
                        onChange={(event) =>
                          updateCurrentVariant(currentVariant.id, (variant) => ({
                            ...variant,
                            cue: event.target.value,
                          }))
                        }
                        className="min-h-[110px]"
                        disabled={!templatesQuery.data?.canEdit}
                      />
                      <p className="text-xs text-muted-foreground">
                        Use this as a subtle pre-visit priming line. Keep it gentle and never turn it into the main CTA.
                      </p>
                    </div>
                  ) : null}

                  {showAskField ? (
                    <div className="grid gap-2">
                      <Label htmlFor="variant-ask">Photo/review ask</Label>
                      <Textarea
                        id="variant-ask"
                        value={currentVariant.ask}
                        onChange={(event) =>
                          updateCurrentVariant(currentVariant.id, (variant) => ({
                            ...variant,
                            ask: event.target.value,
                          }))
                        }
                        className="min-h-[110px]"
                        disabled={!templatesQuery.data?.canEdit}
                      />
                      <p className="text-xs text-muted-foreground">
                        Use this for the direct post-visit ask, like adding a photo alongside the guest&apos;s review.
                      </p>
                    </div>
                  ) : null}

                  {baseTemplate.supportsCtaLabel ? (
                    <div className="grid gap-2">
                      <Label htmlFor="variant-cta-label">CTA label</Label>
                      <Input
                        id="variant-cta-label"
                        value={currentVariant.ctaLabel}
                        onChange={(event) =>
                          updateCurrentVariant(currentVariant.id, (variant) => ({
                            ...variant,
                            ctaLabel: event.target.value,
                          }))
                        }
                        disabled={!templatesQuery.data?.canEdit}
                      />
                    </div>
                  ) : null}

                  <Alert variant="default">
                    <Mail className="size-4" />
                    <AlertTitle>Supported placeholders</AlertTitle>
                    <AlertDescription>
                      Use <code>{'{{firstName}}'}</code>, <code>{'{{venue}}'}</code>, <code>{'{{date}}'}</code>,{' '}
                      <code>{'{{time}}'}</code>, and <code>{'{{party}}'}</code> inside your copy.
                    </AlertDescription>
                  </Alert>
                </div>
              </div>
            </div>
          )}
        </SettingsCard>

        <SettingsCard
          title="Live Preview"
          description="Preview the currently selected variant exactly as the renderer sees it."
          headerAction={
            <Tabs value={previewDevice} onValueChange={(value) => setPreviewDevice(value as 'desktop' | 'mobile')}>
              <TabsList>
                <TabsTrigger value="desktop">
                  <Monitor />
                  Desktop
                </TabsTrigger>
                <TabsTrigger value="mobile">
                  <Smartphone />
                  Mobile
                </TabsTrigger>
              </TabsList>
            </Tabs>
          }
        >
          {previewMutation.isPending && !previewMutation.data ? (
            <Skeleton className="h-[720px] w-full" />
          ) : previewMutation.data ? (
            <Tabs value={previewDevice} className="space-y-4">
              <TabsContent value="desktop" className="mt-0">
                <PreviewCanvas html={previewMutation.data.html} device="desktop" />
              </TabsContent>
              <TabsContent value="mobile" className="mt-0">
                <PreviewCanvas html={previewMutation.data.html} device="mobile" />
              </TabsContent>
            </Tabs>
          ) : (
            <div className="rounded-xl border border-dashed border-border px-4 py-10 text-sm text-muted-foreground">
              Preview data will appear here once a template is selected.
            </div>
          )}
        </SettingsCard>
      </div>
    </div>
  );
}

'use client';

import { Info } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import { cn } from '@/lib/utils';

type HelpTooltipProps = {
  description: string;
  ariaLabel: string;
  className?: string;
  side?: 'top' | 'bottom' | 'left' | 'right';
  align?: 'start' | 'center' | 'end';
};

export function HelpTooltip({
  description,
  ariaLabel,
  className,
  side = 'top',
  align = 'start',
}: HelpTooltipProps) {
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <Button
          type="button"
          variant="ghost"
          size="icon"
          className={cn(
            'inline-flex h-5 w-5 items-center justify-center rounded-full text-muted-foreground transition hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/60',
            className,
          )}
          aria-label={ariaLabel}
        >
          <Info className="size-4" aria-hidden />
        </Button>
      </TooltipTrigger>
      <TooltipContent side={side} align={align} className="max-w-xs text-xs leading-snug">
        {description}
      </TooltipContent>
    </Tooltip>
  );
}

'use client';

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useMemo, useState, type FormEvent } from 'react';

import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { FormRoot } from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Skeleton } from '@/components/ui/skeleton';
import { Switch } from '@/components/ui/switch';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Textarea } from '@/components/ui/textarea';
import { useOccasionService } from '@/contexts/ops-services';
import { useOpsOccasions } from '@/hooks/ops/useOccasions';
import { queryKeys } from '@/lib/query/keys';

import { SettingsCard } from './shared';

import type { OpsOccasion } from '@/services/ops/occasions';

const defaultAvailability = '[\n  {"kind": "anytime"}\n]';

const emptyForm = {
  key: '',
  label: '',
  shortLabel: '',
  description: '',
  defaultDurationMinutes: 90,
  displayOrder: 10,
  availability: defaultAvailability,
  isActive: true,
};

type FormState = typeof emptyForm;

type FormErrors = Partial<Record<keyof FormState, string>>;

export function OccasionsSection() {
  const occasionService = useOccasionService();
  const queryClient = useQueryClient();
  const occasionQuery = useOpsOccasions();

  const [dialogOpen, setDialogOpen] = useState(false);
  const [form, setForm] = useState<FormState>(emptyForm);
  const [formErrors, setFormErrors] = useState<FormErrors>({});
  const [editingKey, setEditingKey] = useState<string | null>(null);

  const occasions = useMemo(() => occasionQuery.data ?? [], [occasionQuery.data]);

  const invalidate = () =>
    queryClient.invalidateQueries({ queryKey: queryKeys.opsOccasions.list() });

  const createMutation = useMutation({
    mutationFn: async (payload: FormState) => {
      const availability = safeParseAvailability(payload.availability);
      return occasionService.createOccasion({
        key: payload.key.trim(),
        label: payload.label.trim(),
        shortLabel: payload.shortLabel.trim() || payload.label.trim(),
        description: payload.description.trim() || null,
        availability,
        defaultDurationMinutes: payload.defaultDurationMinutes,
        displayOrder: payload.displayOrder,
        isActive: payload.isActive,
      });
    },
    onSuccess: async () => {
      await invalidate();
      closeDialog();
    },
    onError: (error: unknown) => {
      console.error('[occasions] create failed', error);
    },
  });

  const updateMutation = useMutation({
    mutationFn: async ({ key, payload }: { key: string; payload: FormState }) => {
      const availability = safeParseAvailability(payload.availability);
      return occasionService.updateOccasion(key, {
        label: payload.label.trim(),
        shortLabel: payload.shortLabel.trim() || payload.label.trim(),
        description: payload.description.trim() || null,
        availability,
        defaultDurationMinutes: payload.defaultDurationMinutes,
        displayOrder: payload.displayOrder,
        isActive: payload.isActive,
      });
    },
    onSuccess: async () => {
      await invalidate();
      closeDialog();
    },
    onError: (error: unknown) => {
      console.error('[occasions] update failed', error);
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (key: string) => occasionService.deleteOccasion(key),
    onSuccess: async () => {
      await invalidate();
    },
    onError: (error: unknown) => {
      console.error('[occasions] delete failed', error);
    },
  });

  const toggleMutation = useMutation<
    unknown,
    unknown,
    { key: string; isActive: boolean },
    { previous?: OpsOccasion[] }
  >({
    mutationFn: async ({ key, isActive }) => occasionService.updateOccasion(key, { isActive }),
    onMutate: async (variables) => {
      await queryClient.cancelQueries({ queryKey: queryKeys.opsOccasions.list() });
      const previous = queryClient.getQueryData<OpsOccasion[]>(queryKeys.opsOccasions.list());
      if (previous) {
        queryClient.setQueryData<OpsOccasion[]>(queryKeys.opsOccasions.list(), (current) =>
          (current ?? []).map((occasion) =>
            occasion.key === variables.key
              ? { ...occasion, isActive: variables.isActive }
              : occasion,
          ),
        );
      }
      return { previous };
    },
    onError: (error, _variables, context) => {
      if (context?.previous) {
        queryClient.setQueryData(queryKeys.opsOccasions.list(), context.previous);
      }
      console.error('[occasions] toggle failed', error);
    },
    onSettled: invalidate,
  });

  const openForCreate = () => {
    const nextOrder =
      occasions.length > 0 ? Math.max(...occasions.map((item) => item.displayOrder)) + 10 : 10;
    setEditingKey(null);
    setForm({ ...emptyForm, displayOrder: nextOrder });
    setFormErrors({});
    setDialogOpen(true);
  };

  const openForEdit = (occasion: OpsOccasion) => {
    setEditingKey(occasion.key);
    setForm({
      key: occasion.key,
      label: occasion.label,
      shortLabel: occasion.shortLabel,
      description: occasion.description ?? '',
      defaultDurationMinutes: occasion.defaultDurationMinutes,
      displayOrder: occasion.displayOrder,
      availability: formatAvailability(occasion.availability),
      isActive: occasion.isActive,
    });
    setFormErrors({});
    setDialogOpen(true);
  };

  const closeDialog = () => {
    setDialogOpen(false);
    setForm({ ...emptyForm });
    setEditingKey(null);
    setFormErrors({});
  };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const errors: FormErrors = {};
    if (!form.label.trim()) errors.label = 'Label is required';
    if (!editingKey && !form.key.trim()) errors.key = 'Key is required';
    if (!editingKey && !/^[a-z0-9_-]+$/.test(form.key.trim()))
      errors.key = 'Use lowercase letters, numbers, dashes, underscores';

    const availabilityResult = tryValidateAvailability(form.availability);
    if (!availabilityResult.valid) {
      errors.availability = availabilityResult.error;
    }

    setFormErrors(errors);
    if (Object.keys(errors).length > 0) return;

    if (editingKey) {
      updateMutation.mutate({ key: editingKey, payload: form });
    } else {
      createMutation.mutate(form);
    }
  };

  const handleDelete = (occasion: OpsOccasion) => {
    if (occasion.isBuiltin) {
      return;
    }
    const confirm = window.confirm(
      `Delete booking type "${occasion.label}"? This cannot be undone.`,
    );
    if (!confirm) return;
    deleteMutation.mutate(occasion.key);
  };

  return (
    <SettingsCard
      title="Booking types"
      description="Control which booking types are available to staff and guests."
      headerAction={<Button onClick={openForCreate}>New booking type</Button>}
    >
      {occasionQuery.isLoading ? (
        <LoadingRows />
      ) : occasions.length === 0 ? (
        <p className="text-sm text-muted-foreground">No booking types configured yet.</p>
      ) : (
        <div className="rounded-lg border">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="w-[180px]">Label</TableHead>
                <TableHead>Short</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Duration</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {occasions.map((occasion) => (
                <TableRow key={occasion.key}>
                  <TableCell className="font-medium flex items-center gap-2">
                    {occasion.label}
                    {occasion.isBuiltin && <Badge variant="secondary">Builtin</Badge>}
                  </TableCell>
                  <TableCell>{occasion.shortLabel}</TableCell>
                  <TableCell>
                    <div className="flex items-center gap-2">
                      <Switch
                        aria-label={`Toggle ${occasion.label}`}
                        checked={occasion.isActive}
                        onCheckedChange={(checked) =>
                          toggleMutation.mutate({ key: occasion.key, isActive: checked })
                        }
                      />
                      <span className="text-sm text-muted-foreground">
                        {occasion.isActive ? 'Active' : 'Inactive'}
                      </span>
                    </div>
                  </TableCell>
                  <TableCell>{occasion.defaultDurationMinutes} min</TableCell>
                  <TableCell className="text-right space-x-2">
                    <Button variant="outline" size="sm" onClick={() => openForEdit(occasion)}>
                      Edit
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      disabled={occasion.isBuiltin}
                      onClick={() => handleDelete(occasion)}
                      className="text-destructive hover:text-destructive"
                    >
                      Delete
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      )}

      <Dialog
        open={dialogOpen}
        onOpenChange={(open) => (!open ? closeDialog() : setDialogOpen(true))}
      >
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{editingKey ? 'Edit booking type' : 'New booking type'}</DialogTitle>
            <DialogDescription>
              Define how the booking type appears in booking flows.
            </DialogDescription>
          </DialogHeader>
          <FormRoot className="space-y-4" onSubmit={handleSubmit}>
            {!editingKey && (
              <div className="space-y-1">
                <Label htmlFor="occasion-key">Key</Label>
                <Input
                  id="occasion-key"
                  value={form.key}
                  onChange={(e) => setForm((prev) => ({ ...prev, key: e.target.value }))}
                  placeholder="e.g., birthday"
                  aria-invalid={Boolean(formErrors.key)}
                />
                {formErrors.key && <p className="text-xs text-destructive">{formErrors.key}</p>}
              </div>
            )}
            <div className="space-y-1">
              <Label htmlFor="occasion-label">Label</Label>
              <Input
                id="occasion-label"
                value={form.label}
                onChange={(e) => setForm((prev) => ({ ...prev, label: e.target.value }))}
                aria-invalid={Boolean(formErrors.label)}
              />
              {formErrors.label && <p className="text-xs text-destructive">{formErrors.label}</p>}
            </div>
            <div className="space-y-1">
              <Label htmlFor="occasion-short">Short label</Label>
              <Input
                id="occasion-short"
                value={form.shortLabel}
                onChange={(e) => setForm((prev) => ({ ...prev, shortLabel: e.target.value }))}
              />
            </div>
            <div className="space-y-1">
              <Label htmlFor="occasion-description">Description</Label>
              <Textarea
                id="occasion-description"
                value={form.description}
                onChange={(e) => setForm((prev) => ({ ...prev, description: e.target.value }))}
                rows={3}
              />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1">
                <Label htmlFor="occasion-duration">Default duration (minutes)</Label>
                <Input
                  id="occasion-duration"
                  type="number"
                  min={1}
                  value={form.defaultDurationMinutes}
                  onChange={(e) =>
                    setForm((prev) => ({ ...prev, defaultDurationMinutes: Number(e.target.value) }))
                  }
                />
              </div>
              <div className="space-y-1">
                <Label htmlFor="occasion-order">Display order</Label>
                <Input
                  id="occasion-order"
                  type="number"
                  value={form.displayOrder}
                  onChange={(e) =>
                    setForm((prev) => ({ ...prev, displayOrder: Number(e.target.value) }))
                  }
                />
              </div>
            </div>
            <div className="space-y-1">
              <Label htmlFor="occasion-availability">Availability rules (JSON array)</Label>
              <Textarea
                id="occasion-availability"
                value={form.availability}
                onChange={(e) => setForm((prev) => ({ ...prev, availability: e.target.value }))}
                rows={5}
                aria-invalid={Boolean(formErrors.availability)}
              />
              {formErrors.availability && (
                <p className="text-xs text-destructive">{formErrors.availability}</p>
              )}
              <p className="text-xs text-muted-foreground">
                {
                  'Use rules like { kind: "anytime" } or time_window/month_only/specific_dates. Leave empty for always available.'
                }
              </p>
            </div>
            <div className="flex items-center gap-2">
              <Switch
                id="occasion-active"
                checked={form.isActive}
                onCheckedChange={(checked) => setForm((prev) => ({ ...prev, isActive: checked }))}
              />
              <Label htmlFor="occasion-active" className="text-sm">
                Active
              </Label>
            </div>
            <DialogFooter className="flex gap-2 sm:gap-2">
              <Button type="button" variant="ghost" onClick={closeDialog}>
                Cancel
              </Button>
              <Button type="submit" disabled={createMutation.isPending || updateMutation.isPending}>
                {editingKey ? 'Save changes' : 'Create'}
              </Button>
            </DialogFooter>
          </FormRoot>
        </DialogContent>
      </Dialog>
    </SettingsCard>
  );
}

function safeParseAvailability(raw: string): unknown[] {
  if (!raw.trim()) return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (error) {
    console.warn(
      '[OccasionsSection] failed to parse availability, defaulting to empty array',
      error,
    );
    return [];
  }
}

function tryValidateAvailability(raw: string): { valid: true } | { valid: false; error: string } {
  if (!raw.trim()) return { valid: true };
  try {
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) {
      return { valid: false, error: 'Availability must be a JSON array' };
    }
    return { valid: true };
  } catch {
    return { valid: false, error: 'Availability must be valid JSON' };
  }
}

function formatAvailability(value: unknown): string {
  if (!value) return defaultAvailability;
  try {
    return JSON.stringify(value, null, 2);
  } catch (error) {
    console.warn('[OccasionsSection] failed to stringify availability', error);
    return defaultAvailability;
  }
}

function LoadingRows() {
  return (
    <div className="space-y-3">
      {Array.from({ length: 3 }).map((_, idx) => (
        <div key={idx} className="flex items-center gap-3">
          <Skeleton className="h-8 w-48" />
          <Skeleton className="h-8 w-24" />
          <Skeleton className="h-8 w-24" />
        </div>
      ))}
    </div>
  );
}

'use client';

import { CalendarIcon, ChevronDownIcon } from 'lucide-react';
import { useMemo, useState } from 'react';

import { Button } from '@/components/ui/button';
import { Calendar } from '@/components/ui/calendar';
import { Label } from '@/components/ui/label';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { cn } from '@/lib/utils';

type OperatingHoursOverrideDateFieldProps = {
  value: string;
  disabled?: boolean;
  error?: string;
  onChange: (value: string) => void;
};

const dateLabelFormatter = new Intl.DateTimeFormat(undefined, {
  weekday: 'short',
  month: 'short',
  day: 'numeric',
  year: 'numeric',
});

function parseDateValue(value: string): Date | undefined {
  if (!value) {
    return undefined;
  }

  const [year, month, day] = value.split('-').map((part) => Number(part));
  if (!year || !month || !day) {
    return undefined;
  }

  const parsed = new Date(year, month - 1, day);
  if (
    Number.isNaN(parsed.getTime()) ||
    parsed.getFullYear() !== year ||
    parsed.getMonth() !== month - 1 ||
    parsed.getDate() !== day
  ) {
    return undefined;
  }

  return parsed;
}

function formatDateValue(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

export function OperatingHoursOverrideDateField({
  value,
  disabled = false,
  error,
  onChange,
}: OperatingHoursOverrideDateFieldProps) {
  const [open, setOpen] = useState(false);

  const selectedDate = useMemo(() => parseDateValue(value), [value]);
  const buttonLabel = selectedDate ? dateLabelFormatter.format(selectedDate) : 'Select date';
  const defaultMonth = selectedDate ?? new Date();

  return (
    <div>
      <div className="flex items-center gap-1">
        <Label className="text-xs uppercase tracking-wide text-muted-foreground">Date</Label>
        <CalendarIcon className="h-3.5 w-3.5 text-muted-foreground" aria-hidden="true" />
      </div>
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <Button
            type="button"
            variant="outline"
            disabled={disabled}
            className={cn(
              'mt-1 h-9 w-full justify-between px-3 text-left text-sm font-normal',
              !selectedDate && 'text-muted-foreground',
              error && 'border-destructive focus-visible:ring-destructive',
            )}
            aria-invalid={Boolean(error)}
          >
            <span className="truncate">{buttonLabel}</span>
            <ChevronDownIcon className="h-4 w-4 shrink-0 opacity-50" aria-hidden="true" />
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-auto overflow-hidden p-0" align="start">
          <Calendar
            mode="single"
            selected={selectedDate}
            defaultMonth={defaultMonth}
            onSelect={(next) => {
              if (!next) {
                return;
              }
              onChange(formatDateValue(next));
              setOpen(false);
            }}
            initialFocus
          />
        </PopoverContent>
      </Popover>
      {error ? <p className="mt-1 text-xs text-destructive">{error}</p> : null}
    </div>
  );
}

'use client';

import { Plus, Trash2 } from 'lucide-react';
import { useCallback, useEffect, useState } from 'react';

import { HelpTooltip } from '@/components/features/restaurant-settings/HelpTooltip';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Skeleton } from '@/components/ui/skeleton';
import { TooltipProvider } from '@/components/ui/tooltip';
import { useOpsOperatingHours, useOpsUpdateOperatingHours } from '@/hooks/ops/useOpsOperatingHours';
import { useGlobalShortcuts } from '@/hooks/useGlobalShortcuts';
import {
  RESERVATION_INTERVAL_MAX,
  RESERVATION_INTERVAL_MIN,
} from '@/lib/restaurants/reservation-interval';
import { cn } from '@/lib/utils';
import { normalizeTime } from '@reserve/shared/time';

import { OperatingHoursOverrideDateField } from './OperatingHoursOverrideDateField';
import { SettingsCard, SettingsSectionHeader } from './shared';
import { DAYS_OF_WEEK } from './types';

import type { OverrideErrors, OverrideRow, WeeklyErrors, WeeklyRow } from './types';
