  restaurantId: string | null;
  embedded?: boolean;
  onDirtyChange?: (dirty: boolean) => void;
};

function DiscoveryFrame({
  embedded,
  title,
  description,
  children,
}: {
  embedded: boolean;
  title: string;
  description: string;
  children: ReactNode;
}) {
  if (embedded) {
    return <div className="space-y-6">{children}</div>;
  }

  return (
    <SettingsCard title={title} description={description}>
      {children}
    </SettingsCard>
  );
