export function ServicePeriodsSection({ restaurantId }: ServicePeriodsSectionProps) {
  const periodsQuery = useOpsServicePeriods(restaurantId);
  const hoursQuery = useOpsOperatingHours(restaurantId);
  const occasionQuery = useOpsOccasions();
  const updateMutation = useOpsUpdateServicePeriods(restaurantId);

  const occasionOptions = useMemo(() => occasionQuery.data ?? [], [occasionQuery.data]);
  const occasionKeys = useMemo(() => extractRequiredOccasionKeys(occasionOptions), [occasionOptions]);

  const [dayConfigs, setDayConfigs] = useState<DayServiceConfig[]>([]);
  const [customRows, setCustomRows] = useState<ServicePeriodRow[]>([]);
  const [errors, setErrors] = useState<DayErrors>({});
  const [isDirty, setIsDirty] = useState(false);

  const weeklyHoursMap = useMemo(
    () =>
      buildWeeklyHoursMap(
        hoursQuery.data?.weekly?.map((row) => ({
          dayOfWeek: row.dayOfWeek,
          opensAt: row.opensAt,
          closesAt: row.closesAt,
          isClosed: row.isClosed,
        })),
      ),
    [hoursQuery.data?.weekly],
  );

  const initializeState = useCallback(() => {
    if (!periodsQuery.data || !hoursQuery.data) {
      return;
    }
    const { days, custom } = buildServicePeriodState({
      periods: periodsQuery.data,
      weeklyHours: weeklyHoursMap,
      dayLabels: DAYS_OF_WEEK,
    });
    setDayConfigs(days);
    setCustomRows(custom);
    setErrors({});
    setIsDirty(false);
  }, [hoursQuery.data, periodsQuery.data, weeklyHoursMap]);

  useEffect(() => {
    initializeState();
  }, [initializeState]);

  const hasRequiredOccasions = Boolean(occasionKeys.lunch && occasionKeys.dinner);

  const handleMealToggle = (dayIndex: number, mealKey: MealKey, value: boolean) => {
    const targetDay = dayConfigs[dayIndex];
    setDayConfigs((current) => {
      const target = current[dayIndex];
      if (!target) return current;
      const next = [...current];
      next[dayIndex] = {
        ...target,
        [mealKey]: {
          ...target[mealKey],
          enabled: value,
        },
      };
      return next;
    });
    setErrors((prev) => {
      if (!targetDay) {
        return prev;
      }
      const next = { ...prev };
      const dayError = { ...(next[targetDay.dayOfWeek] ?? {}) };
      delete dayError[mealKey];
      if (Object.keys(dayError).length === 0) {
        delete next[targetDay.dayOfWeek];
      } else {
        next[targetDay.dayOfWeek] = dayError;
      }
      return next;
    });
    setIsDirty(true);
  };

  const handleMealTimeChange = (dayIndex: number, mealKey: MealKey, field: 'startTime' | 'endTime', value: string) => {
    const targetDay = dayConfigs[dayIndex];
    setDayConfigs((current) => {
      const target = current[dayIndex];
      if (!target) return current;
      const next = [...current];
      next[dayIndex] = {
        ...target,
        [mealKey]: {
          ...target[mealKey],
          [field]: value,
        },
      };
      return next;
    });
    setErrors((prev) => {
      if (!targetDay) {
        return prev;
      }
      const next = { ...prev };
      const dayError = { ...(next[targetDay.dayOfWeek] ?? {}) };
      if (dayError[mealKey]) {
        dayError[mealKey] = { ...dayError[mealKey] };
        delete dayError[mealKey]?.[field === 'startTime' ? 'start' : 'end'];
        if (dayError[mealKey] && Object.keys(dayError[mealKey] as MealError).length === 0) {
          delete dayError[mealKey];
        }
      }
      if (Object.keys(dayError).length === 0) {
        delete next[targetDay.dayOfWeek];
      } else {
        next[targetDay.dayOfWeek] = dayError;
      }
      return next;
    });
    setIsDirty(true);
  };

  const validate = (): boolean => {
    if (dayConfigs.length === 0) {
      return false;
    }
    let valid = true;
    const nextErrors: DayErrors = {};
    dayConfigs.forEach((day) => {
      if (day.isClosed) {
        return;
      }

      (['lunch', 'dinner'] as MealKey[]).forEach((mealKey) => {
        const meal = day[mealKey];
        if (!meal.enabled) {
          return;
        }
        const mealErrors: MealError = {};
        const startComparable = toComparableTime(meal.startTime);
        const endComparable = toComparableTime(meal.endTime);
        const openComparable = toComparableTime(day.opensAt);
        const closeComparable = toComparableTime(day.closesAt);

        if (!meal.startTime) {
          mealErrors.start = 'Required';
        } else if (!openComparable || !startComparable || startComparable < openComparable) {
          mealErrors.start = 'Before kitchen opens';
        }
        if (!meal.endTime) {
          mealErrors.end = 'Required';
        } else if (!closeComparable || !endComparable || endComparable > closeComparable) {
          mealErrors.end = 'After kitchen closes';
        }
        if (
          !mealErrors.start &&
          !mealErrors.end &&
          startComparable &&
          endComparable &&
          startComparable >= endComparable
        ) {
          mealErrors.end = 'Must be after start';
        }
        if (Object.keys(mealErrors).length > 0) {
          valid = false;
          nextErrors[day.dayOfWeek] = {
            ...(nextErrors[day.dayOfWeek] ?? {}),
            [mealKey]: mealErrors,
          };
        }
      });
    });
    setErrors(nextErrors);
    return valid;
  };

  const handleSave = async () => {
    if (!validate()) {
      return;
    }
    if (!hasRequiredOccasions) {
      return;
    }

    const payload = buildServicePeriodPayload(dayConfigs, {
      customRows,
      canonicalizeTime: canonicalizeRequiredTime,
      occasionKeys: {
        lunch: occasionKeys.lunch!,
        dinner: occasionKeys.dinner!,
      },
    });

    try {
      await updateMutation.mutateAsync(payload);
      initializeState();
      setIsDirty(false);
    } catch (error) {
      console.error('[service-periods] save failed', error);
    }
  };

  const handleReset = () => {
    initializeState();
  };

  const isDisabled = updateMutation.isPending || !hasRequiredOccasions;

  useGlobalShortcuts([
    {
      key: 's',
      metaOrCtrl: true,
      preventDefault: true,
      enabled: !isDisabled && isDirty,
      handler: () => {
        if (!isDisabled && isDirty) {
          void handleSave();
        }
      },
    },
  ]);

  if (!restaurantId) {
    return (
      <SettingsCard title="Service Periods">
        <div className="flex min-h-[200px] items-center justify-center py-8">
          <p className="text-sm text-muted-foreground">Select a restaurant to manage service periods</p>
        </div>
      </SettingsCard>
    );
  }

  const loadError = periodsQuery.error ?? hoursQuery.error ?? occasionQuery.error ?? null;
  if (loadError) {
    const message = loadError instanceof Error ? loadError.message : 'Unable to load service periods';
    return (
      <SettingsCard title="Service Periods">
        <Alert variant="destructive">
          <AlertTitle>Unable to load service periods</AlertTitle>
          <AlertDescription>{message}</AlertDescription>
        </Alert>
      </SettingsCard>
    );
  }

  if (
    periodsQuery.isLoading ||
    hoursQuery.isLoading ||
    occasionQuery.isLoading ||
    dayConfigs.length === 0
  ) {
    return (
      <SettingsCard title="Service Periods" description="Loading…">
        <div className="space-y-4">
          <Skeleton className="h-6 w-44" />
          <Skeleton className="h-4 w-72" />
          <div className="grid gap-3 sm:grid-cols-2">
            {Array.from({ length: 6 }).map((_, idx) => (
              <Skeleton key={idx} className="h-28 w-full rounded-lg" />
            ))}
          </div>
        </div>
      </SettingsCard>
    );
  }

  return (
    <TooltipProvider delayDuration={100}>
      <SettingsCard
        title="Service Periods"
        description="Configure kitchen windows for lunch and dinner per day."
        headerAction={
          <HelpTooltip
            description="Lunch and dinner windows must stay inside each day's kitchen hours."
            ariaLabel="Service periods help"
          />
        }
        footer={
          <div className="flex w-full flex-wrap items-center justify-between gap-3">
            <p className="text-xs text-muted-foreground">Lunch & dinner availability follows kitchen windows.</p>
            <div className="flex items-center gap-2 ml-auto">
              <Button type="button" variant="outline" onClick={handleReset} disabled={isDisabled || !isDirty}>
                Reset
              </Button>
              <Button type="button" onClick={handleSave} disabled={isDisabled || !isDirty}>
                Save changes
              </Button>
            </div>
          </div>
        }
      >
        <div className="space-y-4">
          {!hasRequiredOccasions && (
            <Alert variant="destructive">
              <AlertTitle>Missing booking occasions</AlertTitle>
              <AlertDescription>Ensure lunch and dinner occasions exist before editing service periods.</AlertDescription>
            </Alert>
          )}

          {customRows.length > 0 && (
            <Alert>
              <AlertTitle>Additional service periods preserved</AlertTitle>
              <AlertDescription>
                {customRows.length} custom period{customRows.length === 1 ? '' : 's'} exist outside the lunch/dinner
                layout. They will be saved unchanged.
              </AlertDescription>
            </Alert>
          )}

          <div className="space-y-4">
            {dayConfigs.map((day, index) => (
              <div
                key={day.dayOfWeek}
                className="rounded-xl border border-border/70 bg-card/30 p-4 shadow-sm"
                aria-live="polite"
              >
                <div className="flex flex-wrap items-center justify-between gap-3">
                  <div>
                    <p className="text-sm font-semibold text-foreground">{day.label}</p>
                    <p className="text-xs text-muted-foreground">
                      {day.isClosed ? 'Closed' : `Kitchen can operate between ${formatRange(day.opensAt, day.closesAt)}`}
                    </p>
                  </div>
                </div>
                <div className="mt-4 grid gap-4 md:grid-cols-2">
                  <MealEditor
                    label={MEAL_LABELS.lunch}
                    tooltip={MEAL_TOOLTIPS.lunch}
                    meal={day.lunch}
                    disabled={day.isClosed || isDisabled}
                    errors={errors[day.dayOfWeek]?.lunch}
                    onToggle={(value) => handleMealToggle(index, 'lunch', value)}
                    onChange={(field, value) => handleMealTimeChange(index, 'lunch', field, value)}
                  />
                  <MealEditor
                    label={MEAL_LABELS.dinner}
                    tooltip={MEAL_TOOLTIPS.dinner}
                    meal={day.dinner}
                    disabled={day.isClosed || isDisabled}
                    errors={errors[day.dayOfWeek]?.dinner}
                    onToggle={(value) => handleMealToggle(index, 'dinner', value)}
                    onChange={(field, value) => handleMealTimeChange(index, 'dinner', field, value)}
                  />
                </div>
              </div>
            ))}
          </div>
        </div>
      </SettingsCard>
    </TooltipProvider>
  );
}

'use client';

import { Plus, Trash2 } from 'lucide-react';
import { useMemo } from 'react';

import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';

import type { TurnBandInput } from '@/services/ops/restaurants';

export type TurnBandRowError = {
  maxPartySize?: string;
  durationMinutes?: string;
};

type TurnBandsEditorProps = {
  bands: TurnBandInput[];
  defaults?: TurnBandInput[];
  fallbackLabel?: string;
  onChange: (next: TurnBandInput[]) => void;
  errors?: TurnBandRowError[];
  disabled?: boolean;
  dense?: boolean;
};

const sortRows = (rows: TurnBandInput[]): TurnBandInput[] =>
  [...rows].sort((a, b) => a.maxPartySize - b.maxPartySize);

export function describeTurnBands(bands: TurnBandInput[] | undefined, fallback: string): string {
  if (!bands || bands.length === 0) return fallback;
  return bands.map((band) => `≤${band.maxPartySize}: ${band.durationMinutes} min`).join(' · ');
}

export function validateTurnBandRows(rows: TurnBandInput[]): {
  ok: boolean;
  errors: TurnBandRowError[];
} {
  if (!rows || rows.length === 0) {
    return { ok: true, errors: [] };
  }

  const errors: TurnBandRowError[] = rows.map(() => ({}));
  const seenSizes = new Map<number, number[]>();

  rows.forEach((row, index) => {
    const size = Number(row.maxPartySize);
    const duration = Number(row.durationMinutes);

    if (!Number.isInteger(size) || size <= 0) {
      errors[index].maxPartySize = 'Enter a positive whole number.';
    } else {
      const occurrences = seenSizes.get(size) ?? [];
      occurrences.push(index);
      seenSizes.set(size, occurrences);
    }

    if (!Number.isInteger(duration) || duration <= 0) {
      errors[index].durationMinutes = 'Enter a positive whole number.';
    }
  });

  seenSizes.forEach((indices) => {
    if (indices.length > 1) {
      indices.forEach((index) => {
        errors[index] = {
          ...errors[index],
          maxPartySize: 'Max party size must be unique.',
        };
      });
    }
  });

  const ok = errors.every((entry) => Object.keys(entry).length === 0);
  return { ok, errors };
}

export function TurnBandsEditor({
  bands,
  defaults,
  fallbackLabel,
  onChange,
  errors,
  disabled = false,
  dense = false,
}: TurnBandsEditorProps) {
  const hasOverrides = bands.length > 0;
  const effectiveDefaults = useMemo(() => defaults ?? [], [defaults]);

  const defaultsSummary = useMemo(
    () =>
      effectiveDefaults.length > 0
        ? describeTurnBands(effectiveDefaults, fallbackLabel ?? 'No defaults configured')
        : (fallbackLabel ?? 'Defaults will apply until bands are configured.'),
    [effectiveDefaults, fallbackLabel],
  );

  const handleUpdate = (index: number, field: keyof TurnBandInput, rawValue: string) => {
    const parsed = rawValue === '' ? 0 : Number(rawValue);
    const next = bands.map((row, rowIndex) =>
      rowIndex === index ? { ...row, [field]: parsed } : row,
    );
    onChange(next);
  };

  const handleSortOnBlur = () => {
    if (bands.length < 2) return;
    onChange(sortRows(bands));
  };

  const handleAddRow = () => {
    const last = bands[bands.length - 1];
    const defaultSeed = effectiveDefaults[0] ?? null;
    const nextMax = last?.maxPartySize ? last.maxPartySize + 2 : (defaultSeed?.maxPartySize ?? 2);
    const nextDuration = last?.durationMinutes ?? defaultSeed?.durationMinutes ?? 90;
    onChange(sortRows([...bands, { maxPartySize: nextMax, durationMinutes: nextDuration }]));
  };

  const handleRemoveRow = (index: number) => {
    const next = bands.filter((_, rowIndex) => rowIndex !== index);
    onChange(next);
  };

  const handleUseDefaults = () => {
    onChange(sortRows(effectiveDefaults));
  };

  const handleClear = () => {
    onChange([]);
  };

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap items-center justify-end gap-2">
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={handleAddRow}
          disabled={disabled}
        >
          <Plus className="mr-2 size-4" aria-hidden />
          Add band
        </Button>
        {!hasOverrides && effectiveDefaults.length > 0 ? (
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={handleUseDefaults}
            disabled={disabled}
          >
            Use defaults
          </Button>
        ) : null}
        {hasOverrides ? (
          <Button type="button" variant="ghost" size="sm" onClick={handleClear} disabled={disabled}>
            Clear overrides
          </Button>
        ) : null}
      </div>

      {!hasOverrides ? (
        <Alert>
          <AlertTitle>Defaults in use</AlertTitle>
          <AlertDescription className="text-xs text-muted-foreground">
            {defaultsSummary}
          </AlertDescription>
        </Alert>
      ) : (
        <div className={dense ? 'space-y-2' : 'space-y-3'}>
          <div className="grid grid-cols-12 gap-2 text-xs font-medium text-muted-foreground">
            <span className="col-span-5">Max party size</span>
            <span className="col-span-5">Duration (minutes)</span>
            <span className="col-span-2 text-right">Actions</span>
          </div>

          {bands.map((row, index) => {
            const error = errors?.[index] ?? {};
            const sizeId = `turn-band-size-${index}`;
            const durationId = `turn-band-duration-${index}`;
            return (
              <div key={index} className="grid grid-cols-12 items-start gap-2">
                <div className="col-span-5 space-y-1">
                  <Label className="sr-only" htmlFor={sizeId}>
                    Max party size
                  </Label>
                  <Input
                    id={sizeId}
                    type="number"
                    inputMode="numeric"
                    min={1}
                    disabled={disabled}
                    value={
                      Number.isFinite(row.maxPartySize) && row.maxPartySize !== 0
                        ? row.maxPartySize
                        : ''
                    }
                    aria-invalid={Boolean(error.maxPartySize)}
                    onChange={(event) => handleUpdate(index, 'maxPartySize', event.target.value)}
                    onBlur={handleSortOnBlur}
                  />
                  {error.maxPartySize ? (
                    <p className="text-xs text-destructive">{error.maxPartySize}</p>
                  ) : null}
                </div>

                <div className="col-span-5 space-y-1">
                  <Label className="sr-only" htmlFor={durationId}>
                    Duration in minutes
                  </Label>
                  <Input
                    id={durationId}
                    type="number"
                    inputMode="numeric"
                    min={1}
                    disabled={disabled}
                    value={
                      Number.isFinite(row.durationMinutes) && row.durationMinutes !== 0
                        ? row.durationMinutes
                        : ''
                    }
                    aria-invalid={Boolean(error.durationMinutes)}
                    onChange={(event) => handleUpdate(index, 'durationMinutes', event.target.value)}
                  />
                  {error.durationMinutes ? (
                    <p className="text-xs text-destructive">{error.durationMinutes}</p>
                  ) : null}
                </div>

                <div className="col-span-2 flex items-center justify-end pt-1">
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    disabled={disabled}
                    onClick={() => handleRemoveRow(index)}
                    aria-label="Remove band"
                  >
                    <Trash2 className="size-4" aria-hidden />
                  </Button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

'use client';

import { Plus, RotateCcw, Trash2 } from 'lucide-react';
