    businessStatus:
      input.businessStatus === 'open' ||
      input.businessStatus === 'closed_permanently' ||
      input.businessStatus === 'closed_temporarily'
        ? input.businessStatus
        : 'unset',
    isServiceAreaBusiness: input.isServiceAreaBusiness,
  };
}

export function toLinkEditors(input: RestaurantBusinessContextLink[]): LinkEditor[] {
  return filterEditableLinks(input).map((row) => ({
    id: row.id,
    linkType: row.linkType,
    label: row.label ?? '',
    url: row.url,
    isPrimary: row.isPrimary,
  }));
}

export function deriveFamilyCounts(family: RestaurantBusinessContextFamily | null | undefined) {
  return {
    businessDetails: family?.businessDetails ? 1 : 0,
    links: filterEditableLinks(family?.links).length,
    categories: family?.categories.length ?? 0,
    serviceAreas: family?.serviceAreas.length ?? 0,
    attributes: family?.attributes.length ?? 0,
    serviceItems: family?.serviceItems.length ?? 0,
  } satisfies FamilyCounts;
}

export function deriveBusinessContextEditorState(
  snapshot: RestaurantBusinessContextSnapshot,
): BusinessContextEditorState {
  const nextCategories = cloneFamily(
    snapshot.core.categories,
    snapshot.providerSnapshot.categories,
  );
  const nextBusinessDetailsSource = snapshot.core.businessDetails
    ? 'core'
    : snapshot.providerSnapshot.businessDetails
      ? 'provider'
      : 'empty';
  const nextLinks = cloneFamily(
    filterEditableLinks(snapshot.core.links),
    filterEditableLinks(snapshot.providerSnapshot.links),
  );
  const nextServiceAreas = cloneFamily(
    snapshot.core.serviceAreas,
    snapshot.providerSnapshot.serviceAreas,
  );
  const nextAttributes = cloneFamily(
    snapshot.core.attributes,
    snapshot.providerSnapshot.attributes,
  );
  const nextServiceItems = cloneFamily(
    snapshot.core.serviceItems,
    snapshot.providerSnapshot.serviceItems,
  );

  return {
    businessDetails: toBusinessDetailsEditor(
      snapshot.core.businessDetails ?? snapshot.providerSnapshot.businessDetails,
    ),
    links: toLinkEditors(nextLinks.rows),
    categories: toCategoryEditors(nextCategories.rows),
    serviceAreas: toServiceAreaEditors(nextServiceAreas.rows),
    serviceAreaDraft: '',
    attributes: toAttributeEditors(nextAttributes.rows),
    serviceItems: toServiceItemEditors(nextServiceItems.rows),
    seedSource: {
      businessDetails: nextBusinessDetailsSource,
      links: nextLinks.source,
      categories: nextCategories.source,
      serviceAreas: nextServiceAreas.source,
      attributes: nextAttributes.source,
      serviceItems: nextServiceItems.source,
    },
  };
}

export function deriveBusinessContextFamilyState(
  snapshot: RestaurantBusinessContextSnapshot,
  family: FamilyKey,
): Partial<BusinessContextEditorState> {
  const next = deriveBusinessContextEditorState(snapshot);

  if (family === 'businessDetails') {
    return {
      businessDetails: next.businessDetails,
      seedSource: { ...EMPTY_SEED_SOURCE, businessDetails: next.seedSource.businessDetails },
    };
  }

  if (family === 'links') {
    return {
      links: next.links,
      seedSource: { ...EMPTY_SEED_SOURCE, links: next.seedSource.links },
    };
  }

  if (family === 'categories') {
    return {
      categories: next.categories,
      seedSource: { ...EMPTY_SEED_SOURCE, categories: next.seedSource.categories },
    };
  }

  if (family === 'serviceAreas') {
    return {
      serviceAreas: next.serviceAreas,
      serviceAreaDraft: '',
      seedSource: { ...EMPTY_SEED_SOURCE, serviceAreas: next.seedSource.serviceAreas },
    };
  }

  if (family === 'attributes') {
    return {
      attributes: next.attributes,
      seedSource: { ...EMPTY_SEED_SOURCE, attributes: next.seedSource.attributes },
    };
  }

  return {
    serviceItems: next.serviceItems,
    seedSource: { ...EMPTY_SEED_SOURCE, serviceItems: next.seedSource.serviceItems },
  };
}

export function buildBusinessContextFamilyPayload(
  family: FamilyKey,
  state: BusinessContextFamilyPayloadState,
): UpdateRestaurantBusinessContextInput {
  if (family === 'businessDetails') {
    return {
      businessDetails: {
        openingDate: state.businessDetails.openingDate.trim() || null,
        businessStatus:
          state.businessDetails.businessStatus === 'unset'
            ? null
            : state.businessDetails.businessStatus,
        isServiceAreaBusiness: state.businessDetails.isServiceAreaBusiness,
      },
    };
  }

  if (family === 'links') {
    return {
      links: state.links.map((row) => ({
        id: row.id.startsWith('link-') ? undefined : row.id,
        linkType: row.linkType.trim(),
        linkStatus: 'current',
        label: row.label.trim() || null,
        url: row.url.trim(),
        isPrimary: row.isPrimary,
      })),
    };
  }

  if (family === 'categories') {
    const primaryCount = state.categories.filter((row) => row.isPrimary).length;
    if (primaryCount > 1) {
      throw new Error('Only one category can be marked as primary.');
    }

    return {
      categories: state.categories.map((row) => ({
        id: row.id.startsWith('category-') ? undefined : row.id,
        displayName: row.displayName.trim(),
        categoryCode: row.categoryCode.trim() || null,
        isPrimary: row.isPrimary,
        moreHoursTypes: serializeMoreHoursTypes(row.moreHoursTypes),
      })),
    };
  }

  if (family === 'serviceAreas') {
    return {
      serviceAreas: state.serviceAreas.map((row) => ({
        id: row.id.startsWith('service-area-') ? undefined : row.id,
        displayName: row.displayName.trim(),
        areaType: row.areaType.trim() || 'region',
        regionCode: row.regionCode.trim() || null,
        googlePlaceId: row.googlePlaceId.trim() || null,
        googlePlaceResourceName: row.googlePlaceResourceName.trim() || null,
        placeData: parseJsonRecord(row.placeDataJson, 'Place data'),
      })),
    };
  }

  if (family === 'attributes') {
    return {
      attributes: state.attributes.map((row) => ({
        id: row.id.startsWith('attribute-') ? undefined : row.id,
        attributeGroup: row.attributeGroup.trim() || null,
        attributeKey: row.attributeKey.trim(),
        attributeName: row.attributeName.trim() || null,
        attributeId: row.attributeId.trim() || null,
        displayName: row.displayName.trim() || null,
        displayText: row.displayText.trim() || null,
        displayTextStandalone: row.displayTextStandalone.trim() || null,
        displayTextNegative: row.displayTextNegative.trim() || null,
        valueType: row.valueType.trim(),
        boolValue: row.boolValue === 'unset' ? null : row.boolValue === 'true',
        textValue: row.textValue.trim() || null,
        uriValue: row.uriValue.trim() || null,
        uriValues: csvToArray(row.uriValuesText),
        enumValues: csvToArray(row.enumValuesText),
        unsetEnumValues: csvToArray(row.unsetEnumValuesText),
        rawValue: parseJsonRecord(row.rawValueJson, 'Raw value'),
        rawEnumValues: parseJsonRecord(row.rawEnumValuesJson, 'Raw enum values'),
        displayValue: parseJsonRecord(row.displayValueJson, 'Display value'),
        valueMetadata: parseJsonArray(row.valueMetadataJson, 'Value metadata'),
      })),
    };
  }

  return {
    serviceItems: state.serviceItems.map((row) => ({
      id: row.id.startsWith('service-item-') ? undefined : row.id,
      itemKey: row.itemKey.trim(),
      itemType: row.itemType.trim() || null,
      displayName: row.displayName.trim() || null,
      description: row.description.trim() || null,
      payload: parseJsonRecord(row.payloadJson, 'Payload'),
    })),
  };
}

/**
 * Phase 3c of the unified dual-sync engine.
 *
 * Per-field row for the dual-sync workspace. Renders the label, state
 * badge, side-by-side Core vs Google preview, and an action picker that
 * the parent shell aggregates into a `decisions[]` payload for publish.
 */

'use client';

import { Badge } from '@/components/ui/badge';
import { Card, CardContent } from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import { ToggleGroup, ToggleGroupItem } from '@/components/ui/toggle-group';
import { cn } from '@/lib/utils';

import { DualSyncFreshnessChip } from './DualSyncFreshnessChip';
import { DualSyncStateBadge } from './DualSyncStateBadge';

import type { DualSyncDecisionAction } from '@/server/dual-sync';
import type { DualSyncFieldSummary } from '@/services/ops/dual-sync';

export interface DualSyncFieldRowProps {
  readonly field: DualSyncFieldSummary;
  readonly selectedAction: DualSyncDecisionAction | null;
  readonly onChangeAction: (next: DualSyncDecisionAction | null) => void;
  readonly disabled?: boolean;
  readonly className?: string;
}

function formatPreview(value: unknown): string {
  if (value === null || value === undefined) return '—';
  if (typeof value === 'string') return value.length === 0 ? '—' : value;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

function policyLabels(field: DualSyncFieldSummary): string[] {
  const labels: string[] = [];
  switch (field.policy.authority) {
    case 'core_authoritative':
      labels.push('Core-owned');
      break;
    case 'google_authoritative':
      labels.push('Google-owned');
      break;
    case 'review_required':
      labels.push('Manual review');
      break;
    case 'import_only':
      labels.push('Import-only');
      break;
    case 'export_only':
      labels.push('Export-only');
      break;
    case 'read_only':
      labels.push('Read-only');
      break;
    case 'unsupported':
      labels.push('Unsupported by Google');
      break;
    case 'bidirectional_manual':
      break;
  }
  if (field.policy.requiresManualReview && !labels.includes('Manual review')) {
    labels.push('Manual review');
  }
  if (field.policy.riskLevel === 'high' || field.policy.riskLevel === 'critical') {
    labels.push('High-risk field');
  }
  return labels;
}

export function DualSyncFieldRow({
  field,
  selectedAction,
  onChangeAction,
  disabled = false,
  className,
}: DualSyncFieldRowProps) {
  const isUnsupported = field.conflictPolicy === 'unsupported';
  const canImport = field.capability.canImport && !isUnsupported;
  const canExport = field.capability.canExport && !isUnsupported;

  return (
    <Card className={cn('border-border/60', className)}>
      <CardContent className="space-y-3 px-4 py-3">
        <div className="flex flex-wrap items-start justify-between gap-2">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <Label className="text-sm font-semibold">{field.label}</Label>
              <DualSyncStateBadge state={field.state} />
              {field.openCandidate ? (
                <Badge variant="outline" className="text-xs">
                  Pending export queued
                </Badge>
              ) : null}
            </div>
            <div className="flex flex-wrap gap-1">
              {policyLabels(field).map((label) => (
                <Badge key={label} variant="secondary" className="text-[11px] font-medium">
                  {label}
                </Badge>
              ))}
            </div>
            {field.helpText ? (
              <p className="text-muted-foreground text-xs leading-snug">{field.helpText}</p>
            ) : null}
          </div>
          <FieldFreshness field={field} />
        </div>

        <div className="grid gap-3 text-sm md:grid-cols-2">
          <div className="space-y-1">
            <p className="text-muted-foreground text-xs font-medium uppercase tracking-wide">
              Nabatable
            </p>
            <p className="break-words font-mono text-xs">{formatPreview(field.coreValue)}</p>
          </div>
          <div className="space-y-1">
            <p className="text-muted-foreground text-xs font-medium uppercase tracking-wide">
              Google
            </p>
            <p className="break-words font-mono text-xs">{formatPreview(field.gbpValue)}</p>
          </div>
        </div>

        {isUnsupported ? (
          <p className="text-muted-foreground text-xs">
            This field is Nabatable-only. Google has no counterpart.
          </p>
        ) : (
          <ToggleGroup
            type="single"
            value={selectedAction ?? ''}
            onValueChange={(value) => {
              if (!value) {
                onChangeAction(null);
                return;
              }
              onChangeAction(value as DualSyncDecisionAction);
            }}
            className="justify-start gap-2"
            variant="outline"
            size="sm"
          >
            <ToggleGroupItem
              value="import_from_google"
              disabled={!canImport || disabled}
              aria-label="Import from Google"
            >
              Import from Google
            </ToggleGroupItem>
            <ToggleGroupItem
              value="export_to_google"
              disabled={!canExport || disabled}
              aria-label="Export to Google"
            >
              Export to Google
            </ToggleGroupItem>
            <ToggleGroupItem value="ignore" disabled={disabled} aria-label="Ignore field">
              Ignore
            </ToggleGroupItem>
          </ToggleGroup>
        )}

        {field.capability.blockedReasons.length > 0 ? (
          <ul className="text-muted-foreground space-y-0.5 text-[11px]">
            {field.capability.blockedReasons.map((reason) => (
              <li key={reason}>· {reason}</li>
            ))}
          </ul>
        ) : null}
      </CardContent>
    </Card>
  );
}

function FieldFreshness({ field }: { field: DualSyncFieldSummary }) {
  // Pick the most informative timestamp + label for the field's current
  // state. For in_sync we show how long the field has been verified; for
  // drift / conflict / failure states we show how long the divergence
  // has existed.
  switch (field.state) {
    case 'in_sync':
      return field.lastInSyncAt ? (
        <DualSyncFreshnessChip
          timestamp={field.lastInSyncAt}
          prefix="In sync"
          neverLabel="Never verified"
        />
      ) : null;
    case 'core_dirty':
    case 'gbp_dirty':
    case 'drifted': {
      const t = field.lastCoreChangeAt ?? field.lastGbpChangeAt ?? field.lastInSyncAt;
      return t ? (
        <DualSyncFreshnessChip timestamp={t} prefix="Drifted" neverLabel="No history" />
      ) : null;
    }
    case 'conflict': {
      const t = field.lastCoreChangeAt ?? field.lastGbpChangeAt ?? field.lastInSyncAt;
      return t ? (
        <DualSyncFreshnessChip timestamp={t} prefix="In conflict" neverLabel="No history" />
      ) : null;
    }
    case 'pending_import':
    case 'pending_export': {
      const t = field.lastCoreChangeAt ?? field.lastGbpChangeAt ?? field.lastInSyncAt;
      return t ? (
        <DualSyncFreshnessChip timestamp={t} prefix="Pending" neverLabel="No history" />
      ) : null;
    }
    case 'import_failed':
    case 'export_failed': {
      const t = field.lastCoreChangeAt ?? field.lastGbpChangeAt ?? field.lastInSyncAt;
      return t ? (
        <DualSyncFreshnessChip timestamp={t} prefix="Failed" neverLabel="No history" />
      ) : null;
    }
    case null:
    case 'ignored':
    case 'unsupported':
    default:
      return field.lastInSyncAt ? (
        <DualSyncFreshnessChip
          timestamp={field.lastInSyncAt}
          prefix="Last sync"
          neverLabel="Never verified"
        />
      ) : null;
  }
}

/**
 * Phase 3o of the unified dual-sync engine.
 *
 * Tiny chip rendering an age + tone for a dual-sync timestamp. Used
 * inside the shell header (snapshot freshness) and inside the per-field
 * row (in-sync / drift / conflict freshness).
 */

import { Clock } from 'lucide-react';

import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils';

import { freshnessAge, type DualSyncFreshness } from './freshness';

const TONE_CLASS: Record<DualSyncFreshness['tone'], string> = {
  fresh: 'border-primary/30 bg-primary/10 text-primary dark:text-primary',
  recent: 'border-primary/30 bg-primary/10 text-primary dark:text-primary',
  stale: 'border-destructive/50 bg-destructive/10 text-destructive',
  never: 'border-muted-foreground/30 bg-muted/40 text-muted-foreground',
};

const TONE_SUFFIX: Record<DualSyncFreshness['tone'], string> = {
  fresh: 'ago',
  recent: 'ago',
  stale: 'ago',
  never: '',
};

export interface DualSyncFreshnessChipProps {
  readonly timestamp: string | null | undefined;
  /** Optional prefix label, e.g. "Verified" or "In sync". */
  readonly prefix?: string;
  /** Substituted label for the never tone, e.g. "Never verified". */
  readonly neverLabel?: string;
  readonly className?: string;
  /** Pin the relative time against a fixed `now` — used in tests. */
  readonly now?: Date;
}

export function DualSyncFreshnessChip({
  timestamp,
  prefix,
  neverLabel,
  className,
  now,
}: DualSyncFreshnessChipProps) {
  const { tone, label } = freshnessAge(timestamp, now);
  const text =
    tone === 'never'
      ? (neverLabel ?? 'Never')
      : prefix
        ? `${prefix} ${label} ${TONE_SUFFIX[tone]}`.trim()
        : `${label} ${TONE_SUFFIX[tone]}`.trim();
  return (
    <Badge
      variant="outline"
      className={cn(
        'inline-flex items-center gap-1 font-mono text-[10px]',
        TONE_CLASS[tone],
        className,
      )}
      data-tone={tone}
    >
      <Clock className="size-3" />
      {text}
    </Badge>
  );
}

/**
 * Phase 3q of the unified dual-sync engine.
 *
 * Compact horizontal heatmap rendering the proportion of fields per
 * bucket as colored segments. Used in the shell header for the whole
 * restaurant, and inside each section accordion for that section's
 * fields.
 */

import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils';

import {
  HEATMAP_BUCKETS,
  HEATMAP_BUCKET_LABEL,
  HEATMAP_BUCKET_TONE,
  type DualSyncHeatmapBucket,
  type DualSyncHeatmapCounts,
} from './heatmap';

export interface DualSyncHeatmapProps {
  readonly counts: DualSyncHeatmapCounts;
  /** Inline width hint. Defaults to 100% of container. */
  readonly className?: string;
  /** When true, render compact inline counts next to the bar. */
  readonly showLabels?: boolean;
}

export function DualSyncHeatmap({ counts, className, showLabels = true }: DualSyncHeatmapProps) {
  if (counts.total === 0) {
    return (
      <Badge
        variant="outline"
        className={cn(
          'inline-flex items-center gap-1 font-mono text-[10px] text-muted-foreground',
          className,
        )}
      >
        No fields
      </Badge>
    );
  }
  return (
    <div className={cn('flex items-center gap-2', className)}>
      <div
        className="flex h-2 w-32 overflow-hidden rounded-sm border border-border/50"
        role="img"
        aria-label={`Field state breakdown: ${HEATMAP_BUCKETS.map(
          (b) => `${HEATMAP_BUCKET_LABEL[b]} ${counts[b]}`,
        ).join(', ')}`}
      >
        {HEATMAP_BUCKETS.map((bucket) => {
          const value = counts[bucket];
          if (value === 0) return null;
          const widthPct = (value / counts.total) * 100;
          return (
            <div
              key={bucket}
              className={cn('h-full', HEATMAP_BUCKET_TONE[bucket])}
              style={{ width: `${widthPct}%` }}
              title={`${HEATMAP_BUCKET_LABEL[bucket]}: ${value}`}
              data-bucket={bucket}
            />
          );
        })}
      </div>
      {showLabels ? <HeatmapLegend counts={counts} /> : null}
    </div>
  );
}

function HeatmapLegend({ counts }: { counts: DualSyncHeatmapCounts }) {
  const visible = HEATMAP_BUCKETS.filter((b) => counts[b] > 0 && b !== 'inactive');
  if (visible.length === 0) {
    if (counts.inactive === counts.total) {
      return <span className="font-mono text-[10px] text-muted-foreground">all inactive</span>;
    }
    return null;
  }
  return (
    <div className="flex items-center gap-1.5 font-mono text-[10px] text-muted-foreground">
      {visible.map((bucket) => (
        <LegendChip key={bucket} bucket={bucket} value={counts[bucket]} />
      ))}
    </div>
  );
}

function LegendChip({ bucket, value }: { bucket: DualSyncHeatmapBucket; value: number }) {
  return (
    <span className="inline-flex items-center gap-1">
      <span
        aria-hidden="true"
        className={cn('inline-block h-2 w-2 rounded-sm', HEATMAP_BUCKET_TONE[bucket])}
      />
      <span>
        {value}
        <span className="ml-0.5 opacity-70">{shortLabel(bucket)}</span>
      </span>
    </span>
  );
}

function shortLabel(bucket: DualSyncHeatmapBucket): string {
  switch (bucket) {
    case 'in_sync':
      return 'sync';
    case 'drift':
      return 'drift';
    case 'conflict':
      return 'cnflct';
    case 'pending':
      return 'pndg';
    case 'failed':
      return 'fail';
    case 'inactive':
      return 'inact';
  }
}

/**
 * Restaurant-scoped dual-sync operational health panel.
 *
 * Uses the lazy metrics query from `useOpsDualSync` so operators can see
