  readonly publishJobDetailQuery?: UseQueryResult<GetDualSyncPublishJobDetailResponse, Error>;
  readonly colSpan: number;
}

function PublishJobRow({
  job,
  status,
  isSelected,
  detailEnabled,
  onSelectJob,
  publishJobDetailQuery,
  colSpan,
}: PublishJobRowProps) {
  const handleToggle = () => {
    if (!onSelectJob) return;
    onSelectJob(isSelected ? null : job.publishJobId);
  };
  return (
    <>
      <TableRow
        className={cn(
          'text-xs',
          isSelected ? 'bg-muted/40' : undefined,
          detailEnabled ? 'cursor-pointer' : undefined,
        )}
        onClick={detailEnabled ? handleToggle : undefined}
      >
        {detailEnabled ? (
          <TableCell className="w-[28px] align-top">
            <Button
              variant="ghost"
              size="sm"
              className="size-6 p-0"
              onClick={(e) => {
                e.stopPropagation();
                handleToggle();
              }}
              aria-label={isSelected ? 'Hide job detail' : 'Show job detail'}
            >
              {isSelected ? (
                <ChevronDown className="size-3.5" />
              ) : (
                <ChevronRight className="size-3.5" />
              )}
            </Button>
          </TableCell>
        ) : null}
        <TableCell>
          <StatusBadge status={status} />
          {job.errorCodes.length > 0 ? (
            <div className="mt-1 flex flex-wrap gap-1">
              {job.errorCodes.map((code) => (
                <span key={code} className="font-mono text-[10px] text-destructive">
                  {code}
                </span>
              ))}
            </div>
          ) : null}
        </TableCell>
        <TableCell>
          <span className="font-mono text-[10px]" title={job.publishJobId}>
            {shortenJobId(job.publishJobId)}
          </span>
          <div className="mt-0.5 flex gap-2 text-[10px] text-muted-foreground">
            {job.importCount > 0 ? (
              <span className="inline-flex items-center gap-0.5">
                <ArrowDownToLine className="size-3" />
                {job.importCount}
              </span>
            ) : null}
            {job.exportCount > 0 ? (
              <span className="inline-flex items-center gap-0.5">
                <ArrowUpFromLine className="size-3" />
                {job.exportCount}
              </span>
            ) : null}
          </div>
        </TableCell>
        <TableCell className="font-mono text-[10px]">{formatTimestamp(job.startedAt)}</TableCell>
        <TableCell className="text-right font-mono text-[10px]">
          {formatDuration(durationMs(job))}
        </TableCell>
        <TableCell className="text-right font-mono text-[10px]">
          <span className="text-primary">{job.succeededCount}✓</span>
          {' / '}
          <span className="text-destructive">{job.failedCount}✗</span>
          {job.skippedCount > 0 ? (
            <span className="text-muted-foreground">
              {' / '}
              {job.skippedCount}–
            </span>
          ) : null}
        </TableCell>
        <TableCell>
          <div className="flex flex-wrap gap-1">
            {job.sections.map((section) => (
              <Badge key={section} variant="outline" className="font-mono text-[10px]">
                {SECTION_LABEL[section] ?? section}
              </Badge>
            ))}
          </div>
        </TableCell>
      </TableRow>
      {isSelected ? (
        <TableRow className="bg-muted/20">
          <TableCell colSpan={colSpan} className="p-0">
            <PublishJobDetailContent
              jobId={job.publishJobId}
              publishJobDetailQuery={publishJobDetailQuery}
            />
          </TableCell>
        </TableRow>
      ) : null}
    </>
  );
}

const OP_STATUS_VARIANTS: Record<string, 'default' | 'secondary' | 'destructive' | 'outline'> = {
  succeeded: 'default',
  failed: 'destructive',
  skipped: 'outline',
  pending: 'secondary',
  running: 'secondary',
  retrying: 'secondary',
};

interface PublishJobDetailContentProps {
  readonly jobId: string;
  readonly publishJobDetailQuery?: UseQueryResult<GetDualSyncPublishJobDetailResponse, Error>;
}

function PublishJobDetailContent({ jobId, publishJobDetailQuery }: PublishJobDetailContentProps) {
  if (!publishJobDetailQuery) {
    return <div className="p-3 text-xs text-muted-foreground">Detail loader not configured.</div>;
  }
  const isThisJob = publishJobDetailQuery.data?.rollup.publishJobId === jobId;
  if (publishJobDetailQuery.isLoading || (!isThisJob && publishJobDetailQuery.isFetching)) {
    return (
      <div className="space-y-2 p-3">
        <Skeleton className="h-4 w-32" />
        <Skeleton className="h-4 w-full" />
        <Skeleton className="h-4 w-full" />
      </div>
    );
  }
  if (publishJobDetailQuery.isError) {
    return (
      <div className="flex items-start gap-2 p-3 text-xs text-destructive">
        <AlertCircle className="mt-0.5 size-3.5 shrink-0" />
        <div className="space-y-1">
          <div>Couldn&apos;t load job detail.</div>
          <div className="opacity-80">
            {publishJobDetailQuery.error?.message ?? 'Unknown error.'}
          </div>
          <Button variant="outline" size="sm" onClick={() => publishJobDetailQuery.refetch()}>
            Retry
          </Button>
        </div>
      </div>
    );
  }
  const detail = isThisJob ? publishJobDetailQuery.data : undefined;
  if (!detail) {
    return <div className="p-3 text-xs text-muted-foreground">Loading detail…</div>;
  }
  const operations = detail.operations;
  if (operations.length === 0 && detail.operationGroups.length === 0 && !detail.batch) {
    return (
      <div className="p-3 text-xs text-muted-foreground">No operations recorded for this job.</div>
    );
  }
  return (
    <div className="space-y-2 p-3">
      {detail.batch ? (
        <div className="rounded-md border bg-background p-3">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <div>
              <div className="text-[11px] font-semibold text-muted-foreground">Publish batch</div>
              <div className="mt-1 font-mono text-[10px]" title={detail.batch.id}>
                {detail.batch.id}
              </div>
            </div>
            <Badge variant="outline" className="font-mono text-[10px]">
              {detail.batch.status}
            </Badge>
          </div>
          <div className="mt-2 grid gap-2 text-[10px] text-muted-foreground md:grid-cols-4">
            <div>
              <span className="font-semibold text-foreground">{detail.batch.acceptedCount}</span>{' '}
              accepted
            </div>
            <div>
              <span className="font-semibold text-foreground">{detail.batch.rejectedCount}</span>{' '}
              rejected
            </div>
            <div>
              <span className="font-semibold text-foreground">{detail.batch.ignoredCount}</span>{' '}
              ignored
            </div>
            <div className="font-mono">
              {detail.batch.clientRequestId ? detail.batch.clientRequestId : 'no client request'}
            </div>
          </div>
        </div>
      ) : null}

      {detail.operationGroups.length > 0 ? (
        <div className="rounded-md border bg-background">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="w-[100px]">Group</TableHead>
                <TableHead>Write group</TableHead>
                <TableHead className="w-[100px]">Preflight</TableHead>
                <TableHead className="w-[90px] text-right">Fields</TableHead>
                <TableHead className="w-[130px]">Masks</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {detail.operationGroups.map((group) => (
                <TableRow key={group.id} className="text-xs">
                  <TableCell>
                    <Badge
                      variant={OP_STATUS_VARIANTS[group.status] ?? 'outline'}
                      className="font-mono text-[10px]"
                    >
                      {group.status}
                    </Badge>
                    {group.errorCode ? (
                      <div className="mt-1 font-mono text-[10px] text-destructive">
                        {group.errorCode}
                      </div>
                    ) : null}
                  </TableCell>
                  <TableCell>
                    <div className="font-mono text-[10px]">{group.writeGroup}</div>
                    <div className="mt-0.5 text-[10px] text-muted-foreground">
                      {SECTION_LABEL[group.sectionKey] ?? group.sectionKey}
                    </div>
                  </TableCell>
                  <TableCell className="font-mono text-[10px]">
                    {group.preflightStatus ??
                      (group.requiresPreflight ? 'required' : 'not_required')}
                  </TableCell>
                  <TableCell className="text-right font-mono text-[10px]">
                    {group.decisionCount}
                  </TableCell>
                  <TableCell className="font-mono text-[10px]">
                    {group.googleUpdateMasks.length > 0
                      ? group.googleUpdateMasks.join(', ')
                      : 'mask-only'}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      ) : null}

      <div className="text-[11px] font-semibold text-muted-foreground">
        Operations ({operations.length})
      </div>
      <div className="rounded-md border bg-background">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className="w-[110px]">Status</TableHead>
              <TableHead>Field</TableHead>
              <TableHead className="w-[120px]">Direction</TableHead>
              <TableHead className="w-[140px]">Started</TableHead>
              <TableHead>Error</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {operations.map((op) => (
              <TableRow key={op.id} className="text-xs">
                <TableCell>
                  <Badge
                    variant={OP_STATUS_VARIANTS[op.status] ?? 'outline'}
                    className="font-mono text-[10px]"
                  >
                    {op.status}
                  </Badge>
                </TableCell>
                <TableCell className="font-mono text-[10px]">{op.fieldKey}</TableCell>
                <TableCell className="font-mono text-[10px]">
                  {op.direction === 'export_to_google' ? (
                    <span className="inline-flex items-center gap-0.5">
                      <ArrowUpFromLine className="size-3" /> export
                    </span>
                  ) : (
                    <span className="inline-flex items-center gap-0.5">
                      <ArrowDownToLine className="size-3" /> import
                    </span>
                  )}
                </TableCell>
                <TableCell className="font-mono text-[10px]">
                  {formatTimestamp(op.startedAt ?? op.createdAt)}
                </TableCell>
                <TableCell className="text-[11px]">
                  {op.errorCode ? (
                    <span className="font-mono text-destructive">{op.errorCode}</span>
                  ) : (
                    <span className="text-muted-foreground">—</span>
                  )}
                  {op.errorMessage ? (
                    <div
                      className="mt-0.5 text-[10px] text-muted-foreground"
                      title={op.errorMessage}
                    >
                      {op.errorMessage.length > 80
                        ? `${op.errorMessage.slice(0, 80)}…`
                        : op.errorMessage}
                    </div>
                  ) : null}
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>
    </div>
  );
}

/**
 * Publish preview confirmation for unified dual-sync.
 *
 * Renders the read-only section-level plan returned by
 * `/dual-sync/publish/preview` before the operator can execute a write.
 */

'use client';

import { AlertTriangle, ArrowDownToLine, ArrowUpFromLine, ShieldAlert } from 'lucide-react';
import { useEffect, useMemo, useState } from 'react';

import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';

import type {
  DualSyncPlanWarning,
  DualSyncPublishGroup,
  DualSyncPublishPlan,
} from '@/server/dual-sync/publish/types';

const SECTION_LABEL: Record<string, string> = {
  profile: 'Profile',
  operatingHours: 'Operating hours',
  servicePeriods: 'Service periods',
  'businessContext.categories': 'Categories',
  'businessContext.serviceAreas': 'Service areas',
  'businessContext.attributes': 'Attributes',
  'businessContext.serviceItems': 'Service items',
  foodMenus: 'Food menus',
};

const RISK_VARIANT: Record<
  DualSyncPublishGroup['riskLevel'],
  'status-confirmed' | 'status-pending' | 'status-cancelled' | 'status-completed'
> = {
  low: 'status-confirmed',
  medium: 'status-completed',
  high: 'status-pending',
  critical: 'status-cancelled',
};

function sectionLabel(sectionKey: string): string {
  return SECTION_LABEL[sectionKey] ?? sectionKey;
}

function warningLabel(code: DualSyncPlanWarning['code']): string {
  if (code === 'DESTRUCTIVE_WRITE') return 'Destructive write';
  if (code === 'PREFLIGHT_REQUIRED') return 'Preflight required';
  return 'High risk';
}

function requiresAcknowledgement(plan: DualSyncPublishPlan | null): boolean {
  if (!plan) return false;
  return (
    plan.groups.some(
      (group) =>
        group.requiresManualConfirmation ||
        group.destructiveWritePossible ||
        group.riskLevel === 'high' ||
        group.riskLevel === 'critical',
    ) || plan.warnings.length > 0
  );
}

function fieldLabel(count: number): string {
  return count === 1 ? 'field' : 'fields';
}

export interface DualSyncPublishPreviewDialogProps {
  readonly open: boolean;
  readonly plan: DualSyncPublishPlan | null;
  readonly isPublishing: boolean;
  readonly onOpenChange: (open: boolean) => void;
  readonly onConfirm: () => void;
}

export function DualSyncPublishPreviewDialog({
  open,
  plan,
  isPublishing,
  onOpenChange,
  onConfirm,
}: DualSyncPublishPreviewDialogProps) {
  const [acknowledged, setAcknowledged] = useState(false);
  const needsAcknowledgement = useMemo(() => requiresAcknowledgement(plan), [plan]);
  const acceptedCount = plan?.acceptedCount ?? 0;
  const confirmDisabled =
    isPublishing || acceptedCount === 0 || (needsAcknowledgement && !acknowledged);

  useEffect(() => {
    if (open) {
      setAcknowledged(false);
    }
  }, [open, plan]);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-h-[88vh] max-w-4xl overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Review publish plan</DialogTitle>
          <DialogDescription>
            This preview was built from fresh Core and Google snapshots before publish.
          </DialogDescription>
        </DialogHeader>

        {plan ? (
          <div className="flex flex-col gap-4">
            <div className="flex flex-wrap gap-2">
              <Badge variant="metric">{plan.acceptedCount} accepted</Badge>
              <Badge variant={plan.rejectedCount > 0 ? 'status-cancelled' : 'status-confirmed'}>
                {plan.rejectedCount} rejected
              </Badge>
              <Badge variant="secondary">{plan.ignoredCount} ignored</Badge>
              <Badge variant="outline">{plan.groups.length} write groups</Badge>
            </div>

            {plan.warnings.length > 0 ? (
              <Alert variant="warning">
                <ShieldAlert className="size-4" />
                <AlertTitle>High-risk publish review</AlertTitle>
                <AlertDescription>
                  <div className="mt-2 flex flex-col gap-2">
                    {plan.warnings.map((warning, index) => (
                      <div key={`${warning.code}-${warning.groupId ?? index}`} className="text-sm">
                        <span className="font-medium">{warningLabel(warning.code)}:</span>{' '}
                        {warning.message}
                      </div>
                    ))}
                  </div>
                </AlertDescription>
              </Alert>
            ) : null}

            {plan.groups.length > 0 ? <PublishGroupsTable groups={plan.groups} /> : null}

            {plan.rejected.length > 0 ? (
              <div className="rounded-md border border-destructive/40 p-3">
                <div className="mb-2 flex items-center gap-2 text-sm font-semibold text-destructive">
                  <AlertTriangle className="size-4" />
                  Rejected decisions
                </div>
                <div className="flex flex-col gap-2">
                  {plan.rejected.map((rejected) => (
                    <div key={`${rejected.fieldKey}-${rejected.action}`} className="text-xs">
                      <span className="font-mono">{rejected.fieldKey}</span>
                      <span className="text-muted-foreground">
                        {' '}
                        / {rejected.failure.code}: {rejected.failure.message}
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            ) : null}

            {needsAcknowledgement ? (
              <div className="flex items-start gap-2 rounded-md border p-3">
                <Checkbox
                  id="dual-sync-preview-acknowledgement"
                  checked={acknowledged}
                  onCheckedChange={(value) => setAcknowledged(value === true)}
                />
                <Label
                  htmlFor="dual-sync-preview-acknowledgement"
                  className="block text-sm leading-5"
                >
                  I understand this may update public Google Business Profile data.
                </Label>
              </div>
            ) : null}
          </div>
        ) : (
          <Alert>
            <AlertTriangle className="size-4" />
            <AlertTitle>No publish plan loaded.</AlertTitle>
            <AlertDescription>Close this dialog and generate a new preview.</AlertDescription>
          </Alert>
        )}

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={isPublishing}>
            Cancel
          </Button>
          <Button onClick={onConfirm} disabled={confirmDisabled}>
            {isPublishing ? 'Publishing' : `Publish ${acceptedCount} ${fieldLabel(acceptedCount)}`}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

function PublishGroupsTable({ groups }: { readonly groups: ReadonlyArray<DualSyncPublishGroup> }) {
  return (
    <div className="rounded-md border">
      <Table>
        <TableHeader>
          <TableRow>
            <TableHead>Section</TableHead>
            <TableHead className="w-[112px]">Direction</TableHead>
            <TableHead className="w-[96px]">Risk</TableHead>
            <TableHead className="w-[144px]">Masks</TableHead>
            <TableHead className="w-[96px] text-right">Fields</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {groups.map((group) => (
            <TableRow key={group.groupId} className="text-xs">
              <TableCell>
                <div className="font-medium">{sectionLabel(group.sectionKey)}</div>
                <div className="mt-0.5 font-mono text-[10px] text-muted-foreground">
                  {group.writeGroup}
                </div>
              </TableCell>
              <TableCell>
                <span className="inline-flex items-center gap-1 font-mono text-[10px]">
                  {group.direction === 'export_to_google' ? (
                    <>
                      <ArrowUpFromLine className="size-3" />
                      Export
                    </>
                  ) : (
                    <>
                      <ArrowDownToLine className="size-3" />
                      Import
                    </>
                  )}
                </span>
              </TableCell>
              <TableCell>
                <Badge variant={RISK_VARIANT[group.riskLevel]} className="font-mono text-[10px]">
                  {group.riskLevel}
                </Badge>
              </TableCell>
              <TableCell className="font-mono text-[10px]">
                {group.googleUpdateMasks.length > 0 ? group.googleUpdateMasks.join(', ') : '-'}
              </TableCell>
              <TableCell className="text-right font-mono text-[10px]">
                {group.fields.length}
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
}

/**
 * Immediate publish result summary for unified dual-sync.
 */

'use client';

import { AlertCircle, CheckCircle2, CircleDashed, XCircle } from 'lucide-react';

import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';

import type { DualSyncPublishResponse } from '@/services/ops/dual-sync';

const STATUS_VARIANT: Record<string, 'status-confirmed' | 'status-pending' | 'status-cancelled'> = {
  succeeded: 'status-confirmed',
  failed: 'status-cancelled',
  skipped: 'status-pending',
  retrying: 'status-pending',
  pending: 'status-pending',
  running: 'status-pending',
};

function formatTimestamp(value: string | null | undefined): string {
  if (!value) return '-';
  try {
    const d = new Date(value);
    if (Number.isNaN(d.getTime())) return value;
    return d.toLocaleString();
  } catch {
    return value;
  }
}

function titleForResult(result: DualSyncPublishResponse | null): string {
  if (!result) return 'Publish result';
  if (result.failedCount > 0) return 'Publish completed with failures';
  if (result.succeededCount > 0) return 'Publish completed';
  return 'No fields were published';
}

export interface DualSyncPublishResultDialogProps {
  readonly open: boolean;
  readonly result: DualSyncPublishResponse | null;
  readonly onOpenChange: (open: boolean) => void;
}

export function DualSyncPublishResultDialog({
  open,
  result,
  onOpenChange,
}: DualSyncPublishResultDialogProps) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-h-[88vh] max-w-4xl overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{titleForResult(result)}</DialogTitle>
          <DialogDescription>
            Review the operation outcome and any stable failure codes from this publish.
          </DialogDescription>
        </DialogHeader>

        {result ? (
          <div className="flex flex-col gap-4">
            <div className="flex flex-wrap gap-2">
              <Badge variant="status-confirmed">
                <CheckCircle2 className="size-3" />
                {result.succeededCount} succeeded
              </Badge>
              <Badge variant={result.failedCount > 0 ? 'status-cancelled' : 'secondary'}>
                <XCircle className="size-3" />
                {result.failedCount} failed
              </Badge>
              <Badge variant="status-pending">
                <CircleDashed className="size-3" />
                {result.skippedCount} skipped
              </Badge>
            </div>

            {result.failures.length > 0 ? (
              <div className="rounded-md border border-destructive/40 p-3">
                <div className="mb-2 flex items-center gap-2 text-sm font-semibold text-destructive">
                  <AlertCircle className="size-4" />
                  Failure codes
                </div>
                <div className="flex flex-col gap-2">
                  {result.failures.map(({ fieldKey, failure }) => (
                    <div key={`${fieldKey}-${failure.code}`} className="text-xs">
                      <span className="font-mono">{fieldKey}</span>
                      <span className="text-muted-foreground">
                        {' '}
                        / {failure.code}: {failure.message}
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            ) : null}

            {result.operations.length > 0 ? (
              <div className="rounded-md border">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="w-[112px]">Status</TableHead>
                      <TableHead>Field</TableHead>
                      <TableHead className="w-[136px]">Direction</TableHead>
                      <TableHead className="w-[144px]">Mask</TableHead>
                      <TableHead className="w-[168px]">Finished</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {result.operations.map((operation) => (
                      <TableRow key={operation.id} className="text-xs">
                        <TableCell>
                          <Badge
                            variant={STATUS_VARIANT[operation.status] ?? 'status-pending'}
                            className="font-mono text-[10px]"
                          >
                            {operation.status}
                          </Badge>
                        </TableCell>
                        <TableCell>
                          <div className="font-mono text-[10px]">{operation.fieldKey}</div>
                          {operation.errorCode ? (
                            <div className="mt-0.5 font-mono text-[10px] text-destructive">
                              {operation.errorCode}
                            </div>
                          ) : null}
                        </TableCell>
                        <TableCell className="font-mono text-[10px]">
                          {operation.direction}
                        </TableCell>
                        <TableCell className="font-mono text-[10px]">
                          {operation.googleUpdateMask ?? '-'}
                        </TableCell>
                        <TableCell className="font-mono text-[10px]">
                          {formatTimestamp(operation.finishedAt)}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            ) : (
              <div className="rounded-md border border-dashed p-3 text-center text-xs text-muted-foreground">
                No operation rows were returned for this publish.
              </div>
            )}
          </div>
        ) : (
          <div className="rounded-md border border-dashed p-3 text-center text-xs text-muted-foreground">
            No publish result is loaded.
          </div>
        )}

        <DialogFooter>
          <Button onClick={() => onOpenChange(false)}>Done</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * Durable queue recovery panel for unified dual-sync.
 *
 * Uses the lazy `jobsQuery` and `retryJobMutation` exposed by
 * `useOpsDualSync` so operators can see retry/dead-letter state without
 * leaving the settings workspace.
 */

'use client';

