/**
 * Phase 3o of the unified dual-sync engine.
 *
 * Pure helpers for formatting "freshness" / "staleness" of dual-sync
 * timestamps. Used by the shell header chip and the per-field row.
 *
 * The thresholds intentionally bias toward operator visibility:
 *  - "fresh"   : 0 minutes .. 60 minutes
 *  - "recent"  : 60 minutes .. 24 hours
 *  - "stale"   : 24 hours+
 *  - "never"   : timestamp is null/absent
 *
 * The labels are short ("3m", "2h", "5d") so they fit inside chips.
 */

export type DualSyncFreshnessTone = 'fresh' | 'recent' | 'stale' | 'never';

export interface DualSyncFreshness {
  readonly tone: DualSyncFreshnessTone;
  /** Short label like "12m" or "2h". `"—"` when never. */
  readonly label: string;
}

const SECOND = 1_000;
const MINUTE = 60 * SECOND;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

const FRESH_LIMIT = HOUR;
const RECENT_LIMIT = DAY;

export function freshnessAge(
  timestamp: string | null | undefined,
  now: Date = new Date(),
): DualSyncFreshness {
  if (!timestamp) {
    return { tone: 'never', label: '—' };
  }
  const ts = Date.parse(timestamp);
  if (!Number.isFinite(ts)) {
    return { tone: 'never', label: '—' };
  }
  const ageMs = Math.max(0, now.getTime() - ts);
  return {
    tone: classifyAge(ageMs),
    label: formatAge(ageMs),
  };
}

export function classifyAge(ageMs: number): DualSyncFreshnessTone {
  if (!Number.isFinite(ageMs) || ageMs < 0) return 'never';
  if (ageMs < FRESH_LIMIT) return 'fresh';
  if (ageMs < RECENT_LIMIT) return 'recent';
  return 'stale';
}

export function formatAge(ageMs: number): string {
  if (!Number.isFinite(ageMs) || ageMs < 0) return '—';
  if (ageMs < MINUTE) {
    const s = Math.max(1, Math.floor(ageMs / SECOND));
    return `${s}s`;
  }
  if (ageMs < HOUR) {
    const m = Math.max(1, Math.floor(ageMs / MINUTE));
    return `${m}m`;
  }
  if (ageMs < DAY) {
    const h = Math.max(1, Math.floor(ageMs / HOUR));
    return `${h}h`;
  }
  const d = Math.max(1, Math.floor(ageMs / DAY));
  return `${d}d`;
}

/**
 * Phase 3q of the unified dual-sync engine.
 *
 * Pure aggregator that turns the per-field summary returned by
 * `GET /dual-sync/state` into a compact heatmap structure used by the
 * shell header (whole-restaurant) and per-section accordions.
 *
 * The heatmap collapses the 11 raw field states into 4 buckets that
 * map to traffic-light tones, plus an "ignored" / "unsupported" bucket
 * the operator typically does not want to action.
 */

import type { DualSyncFieldSummary } from '@/services/ops/dual-sync';

export type DualSyncHeatmapBucket =
  | 'in_sync'
  | 'drift'
  | 'conflict'
  | 'pending'
  | 'failed'
  | 'inactive';

export interface DualSyncHeatmapCounts {
  readonly total: number;
  readonly in_sync: number;
  readonly drift: number;
  readonly conflict: number;
  readonly pending: number;
  readonly failed: number;
  readonly inactive: number;
  /** Convenience flag: any non in_sync / inactive bucket is non-zero. */
  readonly hasActionableState: boolean;
}

export const HEATMAP_BUCKETS: ReadonlyArray<DualSyncHeatmapBucket> = [
  'in_sync',
  'drift',
  'conflict',
  'pending',
  'failed',
  'inactive',
];

export const HEATMAP_BUCKET_LABEL: Record<DualSyncHeatmapBucket, string> = {
  in_sync: 'In sync',
  drift: 'Drifted',
  conflict: 'Conflict',
  pending: 'Pending',
  failed: 'Failed',
  inactive: 'Inactive',
};

export const HEATMAP_BUCKET_TONE: Record<DualSyncHeatmapBucket, string> = {
  in_sync: 'bg-primary/10',
  drift: 'bg-primary/10',
  conflict: 'bg-destructive',
  pending: 'bg-primary',
  failed: 'bg-destructive',
  inactive: 'bg-muted-foreground/40',
};

const STATE_TO_BUCKET: Record<string, DualSyncHeatmapBucket> = {
  in_sync: 'in_sync',
  core_dirty: 'drift',
  gbp_dirty: 'drift',
  drifted: 'drift',
  conflict: 'conflict',
  pending_import: 'pending',
  pending_export: 'pending',
  import_failed: 'failed',
  export_failed: 'failed',
  ignored: 'inactive',
  unsupported: 'inactive',
};

export function bucketForFieldState(state: string | null | undefined): DualSyncHeatmapBucket {
  if (!state) return 'inactive';
  return STATE_TO_BUCKET[state] ?? 'inactive';
}

export function summarizeFieldsToHeatmap(
  fields: ReadonlyArray<DualSyncFieldSummary>,
): DualSyncHeatmapCounts {
  let in_sync = 0;
  let drift = 0;
  let conflict = 0;
  let pending = 0;
  let failed = 0;
  let inactive = 0;
  for (const field of fields) {
    switch (bucketForFieldState(field.state)) {
      case 'in_sync':
        in_sync += 1;
        break;
      case 'drift':
        drift += 1;
        break;
      case 'conflict':
        conflict += 1;
        break;
      case 'pending':
        pending += 1;
        break;
      case 'failed':
        failed += 1;
        break;
      case 'inactive':
      default:
        inactive += 1;
    }
  }
  const total = fields.length;
  return {
    total,
    in_sync,
    drift,
    conflict,
    pending,
    failed,
    inactive,
    hasActionableState: drift > 0 || conflict > 0 || pending > 0 || failed > 0,
  };
}

/**
 * Derives operator-facing progress for the dual-sync workspace: which fields
 * still need an explicit Import / Export / Ignore choice vs already chosen
 * pending states.
 */

import { bucketForFieldState } from './heatmap';

import type { DualSyncDecisionAction } from '@/server/dual-sync';
import type { DualSyncFieldSummary } from '@/services/ops/dual-sync';

/** Field states where Nabatable and Google differ enough that an operator should decide. */
export function fieldNeedsOperatorChoice(field: DualSyncFieldSummary): boolean {
  if (field.conflictPolicy === 'unsupported') return false;
  const bucket = bucketForFieldState(field.state);
  return bucket === 'drift' || bucket === 'conflict' || bucket === 'failed';
}

export interface WorkspaceReviewProgress {
  readonly totalFields: number;
  readonly inSyncCount: number;
  readonly needsReviewCount: number;
  readonly draftedForReviewCount: number;
  /** Share of visible fields that are in sync with Google (health). */
  readonly syncHealthPercent: number;
  /** Share of “needs review” fields that already have a draft decision. */
  readonly draftCoveragePercent: number;
}

type DecisionMap = Readonly<Record<string, { readonly action: DualSyncDecisionAction }>>;

export function computeWorkspaceReviewProgress(
  fields: ReadonlyArray<DualSyncFieldSummary>,
  decisions: DecisionMap,
): WorkspaceReviewProgress {
  let inSync = 0;
  const needsReview: DualSyncFieldSummary[] = [];
  for (const field of fields) {
    if (bucketForFieldState(field.state) === 'in_sync') {
      inSync += 1;
    }
    if (fieldNeedsOperatorChoice(field)) {
      needsReview.push(field);
    }
  }
  let drafted = 0;
  for (const field of needsReview) {
    if (decisions[field.fieldKey]) {
      drafted += 1;
    }
  }
  const total = fields.length;
  const needsReviewCount = needsReview.length;
  return {
    totalFields: total,
    inSyncCount: inSync,
    needsReviewCount,
    draftedForReviewCount: drafted,
    syncHealthPercent: total === 0 ? 100 : (inSync / total) * 100,
    draftCoveragePercent: needsReviewCount === 0 ? 100 : (drafted / needsReviewCount) * 100,
  };
}

export function computeSectionReviewProgress(
  fields: ReadonlyArray<DualSyncFieldSummary>,
  decisions: DecisionMap,
): Pick<
  WorkspaceReviewProgress,
  'needsReviewCount' | 'draftedForReviewCount' | 'draftCoveragePercent'
> {
  const needsReview = fields.filter(fieldNeedsOperatorChoice);
  const needsReviewCount = needsReview.length;
  let drafted = 0;
  for (const field of needsReview) {
    if (decisions[field.fieldKey]) {
      drafted += 1;
    }
  }
  return {
    needsReviewCount,
    draftedForReviewCount: drafted,
    draftCoveragePercent: needsReviewCount === 0 ? 100 : (drafted / needsReviewCount) * 100,
  };
}

