      label: 'Connection',
      description: workflowSettled ? 'Reconnect if needed.' : 'Authorize access.',
      Icon: ShieldCheck,
      onSelect: () => onSelectAnchor('gbp-connection'),
      badge: workflowSettled ? undefined : stepBadgeLabel(connectionStatus),
