              ) : null}
            </AlertDescription>
          </Alert>
        ) : null}

        {!hasLocations ? (
          <Alert>
            <AlertTitle>No accessible locations</AlertTitle>
            <AlertDescription>
              Authorization succeeded, but this Google account does not currently expose any
              Business Profile locations.
            </AlertDescription>
