'use client';

import { cn } from '@/lib/utils';

type ReadinessRingProps = {
  /** Percent complete, 0-100. */
  value: number;
  /** Total items represented (for the inner caption). */
  total: number;
  /** Items completed (for the inner caption). */
  completed: number;
  /** Pixel size of the ring; default 96. */
  size?: number;
  /** Stroke width in pixels; default 8. */
  stroke?: number;
  className?: string;
};

/**
 * Circular completion indicator used in the Profile header. Values clamp to
 * 0–100. Accessible via `role="img"` + `aria-label`; the visible inner text is
 * marked aria-hidden to avoid double-announcement.
 */
export function ReadinessRing({
  value,
  total,
  completed,
  size = 96,
  stroke = 8,
  className,
}: ReadinessRingProps) {
  const safeValue = Math.min(Math.max(Number.isFinite(value) ? value : 0, 0), 100);
  const radius = (size - stroke) / 2;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (safeValue / 100) * circumference;
  const isComplete = safeValue >= 100;
  const progressTone = isComplete
    ? 'text-primary'
    : safeValue >= 60
      ? 'text-warning'
      : 'text-destructive';

  return (
    <div
      role="img"
      aria-label={`Profile readiness ${Math.round(safeValue)}%, ${completed} of ${total} fields complete`}
      className={cn('relative inline-flex items-center justify-center', className)}
      style={{ width: size, height: size }}
    >
      <svg
        width={size}
        height={size}
        viewBox={`0 0 ${size} ${size}`}
        aria-hidden
        className="-rotate-90"
      >
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          stroke="currentColor"
          strokeWidth={stroke}
          fill="none"
          className="text-muted/40"
        />
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          stroke="currentColor"
          strokeWidth={stroke}
          strokeLinecap="round"
          fill="none"
          strokeDasharray={circumference}
          strokeDashoffset={offset}
          className={cn('transition-[stroke-dashoffset] duration-500 ease-out', progressTone)}
        />
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center" aria-hidden>
        <span className="text-xl font-semibold tabular-nums leading-none text-foreground">
          {Math.round(safeValue)}%
        </span>
        <span className="mt-1 text-[10px] uppercase tracking-wider text-muted-foreground">
          {completed}/{total}
        </span>
      </div>
    </div>
  );
}

'use client';

import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';

import type { ProfileSectionDefinition } from './profileSections';
import type { ProfileDirtySection } from '../restaurantProfileModel';

type UnifiedActionBarProps = {
  dirtyFormSections: readonly (ProfileDirtySection & { formId: string })[];
  discoveryDirty: boolean;
  activeSection: ProfileSectionDefinition;
  lastSavedAt: string | null;
  onSaveAll: () => void;
  onOpenDiscovery: () => void;
  className?: string;
};

function formatSavedAt(value: string | null): string {
  if (!value) {
    return 'No saved timestamp yet';
  }

  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return value;
  }

  return new Intl.DateTimeFormat('en-GB', {
    dateStyle: 'medium',
    timeStyle: 'short',
  }).format(parsed);
}

export function UnifiedActionBar({
  dirtyFormSections,
  discoveryDirty,
  activeSection,
  lastSavedAt,
  onSaveAll,
  onOpenDiscovery,
  className,
}: UnifiedActionBarProps) {
  const profileDirtyCount = dirtyFormSections.length;
  const activeDirtySection = dirtyFormSections.find(
    (section) => section.key === activeSection.dirtyKey,
  );

  if (profileDirtyCount === 0 && !discoveryDirty) {
    return (
      <div
        role="status"
        className={cn(
          'rounded-md border border-border/60 bg-muted/20 px-3 py-2 text-sm text-muted-foreground',
          className,
        )}
      >
        <p>
          Last profile save: <span className="text-foreground">{formatSavedAt(lastSavedAt)}</span>.
          Save controls appear here when a profile section or Discovery has a draft.
        </p>
      </div>
    );
  }

  const title =
    profileDirtyCount > 0
      ? `${profileDirtyCount} unsaved profile section${profileDirtyCount === 1 ? '' : 's'}`
      : 'Discovery has unsaved draft changes';
  const description =
    profileDirtyCount > 0 && discoveryDirty
      ? 'Profile sections save from this bar. Discovery saves inside its own drawer.'
      : profileDirtyCount > 0
        ? 'Save profile changes without leaving this command center.'
        : 'Open Discovery to review and save its panel-level draft.';

  return (
    <Alert
      className={cn(
        'sticky bottom-0 z-10 border-primary/30 bg-background/95 px-3 py-2 pb-[max(0.5rem,env(safe-area-inset-bottom))] shadow-lg backdrop-blur supports-[backdrop-filter]:bg-background/85',
        className,
      )}
    >
      <AlertTitle>{title}</AlertTitle>
      <AlertDescription className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <span>{description}</span>
        <div className="flex flex-wrap items-center gap-2">
          {activeDirtySection ? (
            <Button type="submit" form={activeDirtySection.formId} size="sm">
              {activeDirtySection.actionLabel}
            </Button>
          ) : null}
          {profileDirtyCount > 1 ? (
            <Button
              type="button"
              variant={activeDirtySection ? 'outline' : 'default'}
              size="sm"
              onClick={onSaveAll}
            >
              Save all
            </Button>
          ) : null}
          {discoveryDirty ? (
            <Button type="button" variant="outline" size="sm" onClick={onOpenDiscovery}>
              Review discovery draft
            </Button>
          ) : null}
        </div>
      </AlertDescription>
    </Alert>
  );
}

