): RestaurantDetailsFormValues {
  if (!profile) {
    return EMPTY_PROFILE_VALUES;
  }

  return {
    name: profile.name,
    slug: profile.slug ?? '',
    timezone: profile.timezone ?? COMMON_TIMEZONES[0],
