          <div className="min-w-0">
            <div className="text-sm font-semibold text-foreground">Table {table.tableNumber}</div>
            <div className="mt-0.5 flex items-center gap-1.5 text-[11px] text-muted-foreground">
              <MapPin className="h-3 w-3" />
              <span className="truncate">{table.zoneName ?? 'No zone'}</span>
            </div>
          </div>
          <span className="rounded-md bg-muted px-2 py-1 text-[10px] font-semibold text-muted-foreground">
            Cap {table.capacity}
          </span>
        </div>
      </div>

      <div className="relative h-14 flex-1" style={{ minWidth: `${TIME_SLOTS.length * SLOT_WIDTH_PX}px` }}>
        <div className="absolute inset-0 flex">
          {TIME_SLOTS.map((slot) => (
            <div
              key={slot}
              className="h-full shrink-0 border-r border-border/30"
              style={{ width: SLOT_WIDTH_PX }}
              aria-hidden
            />
          ))}
        </div>

        <div className="absolute inset-y-0 z-20 w-px bg-rose-500" style={{ left: `${nowPx}px` }} aria-hidden>
          <div className="absolute -top-1 -left-1 h-2 w-2 rounded-full bg-rose-500 shadow" />
        </div>

        {segments
          .filter((segment) => segment.state !== 'available')
          .map((segment, idx) => (
            <PrototypeReservationBlock
              key={`${segment.start}-${segment.end}-${idx}`}
              segment={segment}
              windowStart={windowStart}
              windowEnd={windowEnd}
              timelineWidthPx={timelineWidthPx}
              onClick={() => onSelect(segment)}
            />
          ))}
      </div>
    </div>
  );
}

function PrototypeReservationBlock({
  segment,
  windowStart,
  windowEnd,
  timelineWidthPx,
  onClick,
}: {
  segment: TableTimelineSegment;
  windowStart: string;
  windowEnd: string;
  timelineWidthPx: number;
  onClick: () => void;
}) {
  const state = segment.state;
  const statusStyle: Record<TableTimelineSegmentState, string> = {
    reserved: 'bg-blue-600 text-white border-blue-700',
    hold: 'bg-amber-500 text-slate-950 border-amber-600',
    available: 'bg-muted text-muted-foreground border-border',
    out_of_service: 'bg-slate-500 text-white border-slate-600',
  };

  const start = toHHMM(segment.start);
  const end = toHHMM(segment.end);

  const left = clampToServiceWindow(timeToPositionPx(start), windowStart, windowEnd) - timeToPositionPx(windowStart);
  const right = clampToServiceWindow(timeToPositionPx(end), windowStart, windowEnd) - timeToPositionPx(windowStart);
  const width = Math.max(0, right - left);
  if (width <= 0) return null;

  const customerLabel = segment.booking?.customerName ?? STATUS_META[state].label;
  const partySize = segment.booking?.partySize ?? null;

  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        'absolute top-2 h-10 rounded-lg border-l-4 px-3 text-left shadow-sm transition hover:brightness-110',
        statusStyle[state],
      )}
      style={{ left, width: Math.min(width, timelineWidthPx - left) }}
      aria-label={`${customerLabel} ${start}–${end}`}
    >
      <div className="flex items-center justify-between gap-2 overflow-hidden">
        <span className="truncate text-[11px] font-semibold">{customerLabel}</span>
        {partySize ? (
          <span className="flex items-center gap-1 text-[10px] opacity-80">
            <Users className="h-3 w-3" /> {partySize}
          </span>
        ) : null}
      </div>
      <div className="truncate text-[10px] opacity-80">
        {start} – {end}
      </div>
    </button>
  );
}

function SegmentDialog({
  selected,
  onClose,
  onReleaseHold,
  actionState,
}: {
  selected: SelectedSegment | null;
  onClose: () => void;
  onReleaseHold: (holdId: string, bookingId: string | null) => void;
  actionState: { releasing: boolean; error: string | null };
}) {
  if (!selected) return null;

  const { table, segment } = selected;
  const start = formatTime(segment.start);
  const end = formatTime(segment.end);
  const durationMinutes = Math.max(
    Math.round((new Date(segment.end).getTime() - new Date(segment.start).getTime()) / 60000),
    0,
  );
  const holdId = segment.hold?.id ?? null;
  const bookingId = segment.hold?.bookingId ?? segment.booking?.id ?? null;
  const meta = STATUS_META[segment.state];

  return (
    <Dialog open onOpenChange={(next) => { if (!next) onClose(); }}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader className="space-y-2">
          <div className="flex items-center gap-3">
            <div className="flex h-12 w-12 items-center justify-center rounded-xl bg-muted text-lg font-semibold text-foreground">
              T{table.tableNumber}
            </div>
            <div className="space-y-1 text-left">
              <DialogTitle>Table {table.tableNumber}</DialogTitle>
              <DialogDescription className="flex items-center gap-2 text-sm">
                <Clock className="h-4 w-4" />
                {start} – {end}
                {durationMinutes ? ` (${durationMinutes}m)` : ''}
              </DialogDescription>
            </div>
          </div>
          <div className="flex items-center gap-2 text-sm text-muted-foreground">
            <MapPin className="h-4 w-4" />
            <span>{table.zoneName ?? 'No zone'}</span>
            <span className="text-border">•</span>
            <Users className="h-4 w-4" />
            <span>{table.capacity} seats</span>
          </div>
        </DialogHeader>

        <div className={cn('rounded-xl border p-4', meta.bg, meta.border)}>
          <div className="flex items-start gap-3">
            <Badge className={cn('flex-shrink-0', meta.chip)}>{meta.label}</Badge>
            <div className="space-y-1 text-sm">
              {segment.booking ? (
                <>
                  <p className="font-semibold text-foreground">{segment.booking.customerName ?? 'Guest'}</p>
                  <p className="text-muted-foreground">Party of {segment.booking.partySize} · {segment.booking.status}</p>
                </>
              ) : segment.state === 'hold' ? (
                <>
                  <p className="font-semibold text-foreground">Table is on hold</p>
                  <p className="text-muted-foreground">Linked booking ID: {bookingId ?? 'unknown'}</p>
                </>
              ) : segment.state === 'out_of_service' ? (
                <>
                  <p className="font-semibold text-foreground">Out of service</p>
                  <p className="text-muted-foreground">Temporarily unavailable</p>
                </>
              ) : (
                <>
                  <p className="font-semibold text-foreground">Available slot</p>
                  <p className="text-muted-foreground">Ready to be assigned</p>
                </>
              )}
            </div>
          </div>
        </div>

        <div className="flex flex-wrap gap-2 pt-1">
          {segment.booking ? (
            <Button asChild className="flex-1">
              <a href={`/bookings?query=${encodeURIComponent(segment.booking.customerName ?? '')}`}>
                View booking
                <ChevronRight className="ml-2 h-4 w-4" />
              </a>
            </Button>
          ) : null}
          {segment.state === 'hold' ? (
            <Button
              className="flex-1"
              variant="outline"
              disabled={!holdId || !bookingId || actionState.releasing}
              onClick={() => holdId && onReleaseHold(holdId, bookingId)}
            >
              {actionState.releasing ? 'Releasing hold…' : 'Release hold'}
            </Button>
          ) : null}
          {segment.state === 'available' ? (
            <Button className="flex-1" variant="secondary" disabled>
              Create booking
            </Button>
          ) : null}
        </div>
        {actionState.error ? <p className="text-xs text-destructive">{actionState.error}</p> : null}
      </DialogContent>
    </Dialog>
  );
}

function formatTime(date: string) {
  return new Date(date).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
}

'use client';

import { ShieldCheck, UserPlus, Users } from 'lucide-react';
import { useCallback, useState } from 'react';

import { RestaurantSettingsCommandCenter } from '@/components/features/restaurant-settings/shared';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Skeleton } from '@/components/ui/skeleton';
import { useOpsActiveMembership, useOpsSession } from '@/contexts/ops-session';
import { isRestaurantAdminRole } from '@/lib/owner/auth/roles';

import { TeamInviteForm } from './TeamInviteForm';
import { TeamInvitesTable } from './TeamInvitesTable';

type TeamWorkspace = 'invite' | 'invitations';

export function OpsTeamManagementClient() {
  const { memberships, activeRestaurantId, permissions } = useOpsSession();
  const activeMembership = useOpsActiveMembership();
  const [activeWorkspace, setActiveWorkspace] = useState<TeamWorkspace>('invite');
  const selectWorkspace = useCallback((workspace: TeamWorkspace) => {
    setActiveWorkspace(workspace);
    window.history.replaceState(
      null,
      '',
      workspace === 'invite' ? '#team-invite' : '#team-invitations',
    );
  }, []);

  if (memberships.length === 0) {
    return (
      <Alert variant="destructive">
        <AlertTitle>No restaurant access</AlertTitle>
        <AlertDescription>
          Your account is not linked to any restaurants yet. Ask an owner or manager to send you an
          invitation.
        </AlertDescription>
      </Alert>
    );
  }

  if (!activeRestaurantId || !activeMembership) {
    return <Skeleton className="h-36 w-full" />;
  }

  const canManage = permissions.canManageTeam || isRestaurantAdminRole(activeMembership.role);
  const visibleWorkspace = canManage ? activeWorkspace : 'invitations';

  return (
    <RestaurantSettingsCommandCenter
      eyebrow="Team command center"
      title="Team"
      description="Invite staff, review pending access, and keep team permissions clear without leaving restaurant settings."
      metrics={[
        {
          label: 'Your role',
          value: activeMembership.role,
          description: canManage ? 'can manage invites' : 'view-only team access',
          variant: canManage ? 'default' : 'secondary',
          Icon: ShieldCheck,
        },
        {
          label: 'Invite access',
          value: canManage ? 'Enabled' : 'Limited',
          description: 'owners and managers only',
          variant: canManage ? 'secondary' : 'metric',
          Icon: UserPlus,
        },
      ]}
      railTitle="Team workflow"
      railDescription="Invite first, then review pending or accepted invitations below."
      railItems={[
        ...(canManage
          ? [
              {
                label: 'Invite member',
                description: 'Send access to a manager or host.',
                href: '#team-invite',
                Icon: UserPlus,
                isActive: visibleWorkspace === 'invite',
                onSelect: () => selectWorkspace('invite'),
              },
            ]
          : []),
        {
          label: 'Invitations',
          description: 'Review pending, accepted, expired, or revoked invites.',
          href: '#team-invitations',
          Icon: Users,
          isActive: visibleWorkspace === 'invitations',
          onSelect: () => selectWorkspace('invitations'),
        },
      ]}
      footer="Role rules stay unchanged: only owners and managers can send or revoke invitations."
    >
      <div className="flex flex-col gap-6">
        {!canManage ? (
          <Alert>
            <AlertTitle>Limited permissions</AlertTitle>
            <AlertDescription>
              Only owners and managers can send invitations. Contact an owner if you need to add
              teammates.
            </AlertDescription>
          </Alert>
        ) : null}

        <section className="flex flex-col gap-6">
          {canManage ? (
            <div
              id="team-invite"
              hidden={visibleWorkspace !== 'invite'}
              className={visibleWorkspace !== 'invite' ? 'hidden scroll-mt-28' : 'scroll-mt-28'}
            >
              <TeamInviteForm restaurantId={activeRestaurantId} />
            </div>
          ) : null}
          <div
            id="team-invitations"
            hidden={visibleWorkspace !== 'invitations'}
            className={visibleWorkspace !== 'invitations' ? 'hidden scroll-mt-28' : 'scroll-mt-28'}
          >
            <TeamInvitesTable restaurantId={activeRestaurantId} canManage={canManage} />
          </div>
        </section>
      </div>
    </RestaurantSettingsCommandCenter>
  );
}

